package thebetweenlands.common.block.container;

import java.util.List;
import java.util.Random;

import net.minecraft.block.ITileEntityProvider;
import net.minecraft.block.SoundType;
import net.minecraft.block.material.Material;
import net.minecraft.block.state.BlockFaceShape;
import net.minecraft.block.state.IBlockState;
import net.minecraft.client.util.ITooltipFlag;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.InventoryHelper;
import net.minecraft.item.Item;
import net.minecraft.item.ItemBlock;
import net.minecraft.item.ItemStack;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.BlockRenderLayer;
import net.minecraft.util.EnumBlockRenderType;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumHand;
import net.minecraft.util.EnumParticleTypes;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.text.translation.I18n;
import net.minecraft.world.IBlockAccess;
import net.minecraft.world.World;
import net.minecraftforge.fluids.Fluid;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.client.handler.ItemTooltipHandler;
import thebetweenlands.client.render.particle.BLParticles;
import thebetweenlands.client.render.particle.ParticleFactory.ParticleArgs;
import thebetweenlands.client.tab.BLCreativeTabs;
import thebetweenlands.common.block.terrain.BlockSwampWater;
import thebetweenlands.common.item.misc.ItemMisc.EnumItemMisc;
import thebetweenlands.common.registries.BlockRegistry.ICustomItemBlock;
import thebetweenlands.common.registries.BlockRegistry.IStateMappedBlock;
import thebetweenlands.common.registries.FluidRegistry;
import thebetweenlands.common.tile.TileEntityCrabPot;
import thebetweenlands.util.AdvancedStateMap;

public class BlockCrabPot extends BlockSwampWater implements ITileEntityProvider, IStateMappedBlock {

	public BlockCrabPot() {
		this(FluidRegistry.SWAMP_WATER, Material.WATER);
		this.setHardness(0.5F);
	}

	public BlockCrabPot(Fluid fluid, Material materialIn) {
		super(fluid, materialIn);
		setHardness(0.5F);
		setResistance(5.0F);
		setSoundType(SoundType.WOOD);
		setCreativeTab(BLCreativeTabs.BLOCKS);
		this.setUnderwaterBlock(true);
		this.setDefaultState(blockState.getBaseState().withProperty(LEVEL, 0));
	}

	@Override
	@SideOnly(Side.CLIENT)
	public void setStateMapper(AdvancedStateMap.Builder builder) {
		super.setStateMapper(builder);
		builder.ignore(LEVEL);
	}

	@Override
    public void addInformation(ItemStack stack, World player, List<String> tooltip, ITooltipFlag advanced) {
		tooltip.addAll(ItemTooltipHandler.splitTooltip(I18n.translateToLocalFormatted("tooltip.bl.crab_pot_item"), 0));
        super.addInformation(stack, player, tooltip, advanced);
    }

	@Override
	public void onBlockPlacedBy(World world, BlockPos pos, IBlockState state, EntityLivingBase placer, ItemStack stack) {
		if (!world.isRemote) {
			if (world.getTileEntity(pos) instanceof TileEntityCrabPot) {
				TileEntityCrabPot tile = (TileEntityCrabPot) world.getTileEntity(pos);
				tile.setRotation(placer.getHorizontalFacing().rotateYCCW().getHorizontalIndex());
				if(placer instanceof EntityPlayer)
					tile.setPlacer((EntityPlayer) placer);
				tile.markForUpdate();
			}
		}
	}

	@Override
	public boolean canPlaceBlockAt(World world, BlockPos pos) {
		return super.canPlaceBlockAt(world, pos) && !(world.getBlockState(pos).getBlock() instanceof BlockCrabPotFilter);
	}

	@Override
	public TileEntity createNewTileEntity(World worldIn, int meta) {
		return new TileEntityCrabPot();
	}

	@Override
	public void onBlockClicked(World world, BlockPos pos, EntityPlayer player) {
		if (!world.isRemote) {

		}
	}

	@Override
	public boolean onBlockActivated(World world, BlockPos pos, IBlockState state, EntityPlayer player, EnumHand hand, EnumFacing side, float hitX, float hitY, float hitZ) {
		if(world.isRemote)
			return true;

		if (!world.isRemote) {
			if (world.getTileEntity(pos) instanceof TileEntityCrabPot) {
				TileEntityCrabPot tile = (TileEntityCrabPot) world.getTileEntity(pos);
				if (!player.getHeldItem(hand).isEmpty() && tile.getStackInSlot(0).isEmpty()) {
					ItemStack stack = player.getHeldItem(hand).splitStack(1);
					if (!stack.isEmpty()) {
						tile.setInventorySlotContents(0, stack);
						tile.markForUpdate();
						return true;
					}
				} else if (!tile.getStackInSlot(0).isEmpty()) {
					ItemStack extracted = tile.getStackInSlot(0);
					if (!extracted.isEmpty()) {
						EntityItem item = new EntityItem(world, pos.getX() + 0.5D, pos.getY() + 1.0D, pos.getZ() + 0.5D, extracted);
						item.motionX = item.motionY = item.motionZ = 0D;
						world.spawnEntity(item);
						tile.setInventorySlotContents(0, ItemStack.EMPTY);
						tile.markForUpdate();
						return true;
					}
				}
			}
		}
		return false;
	}

	@Override
	public void breakBlock(World world, BlockPos pos, IBlockState state) {
		TileEntityCrabPot tile = (TileEntityCrabPot) world.getTileEntity(pos);
		if (tile != null) 
			InventoryHelper.dropInventoryItems(world, pos, tile);
		super.breakBlock(world, pos, state);
	}

	@SideOnly(Side.CLIENT)
	@Override
	public void randomDisplayTick(IBlockState state, World world, BlockPos pos, Random rand) {
		TileEntityCrabPot tile = (TileEntityCrabPot) world.getTileEntity(pos);
		if (tile != null)
			if (!tile.hasBaitItem() && !tile.getStackInSlot(0).isEmpty() && tile.getEntity() != null) {
				if (rand.nextInt(3) == 0)
					world.spawnParticle(EnumParticleTypes.WATER_BUBBLE, pos.getX() + 0.5D, pos.getY() + 0.5D + (float) tile.fallCounter * 0.03125F, pos.getZ() + 0.5D, 0.0D, 0.3D, 0.0D, new int[0]);
				if (tile.fallCounter >= 1 && tile.fallCounter < 16)
					for (int count = 0; count < 10; ++count)
						BLParticles.ITEM_BREAKING.spawn(world, pos.getX() + 0.5D + (world.rand.nextDouble() - 0.5D), pos.getY() + 0.5D + world.rand.nextDouble(), pos.getZ() + 0.5D + (world.rand.nextDouble() - 0.5D), ParticleArgs.get().withData(EnumItemMisc.ANADIA_REMAINS.create(1)));
			}
	}

	@Override
	public EnumBlockRenderType getRenderType(IBlockState state) {
		return EnumBlockRenderType.MODEL;
	}

	@SideOnly(Side.CLIENT)
	@Override
	public boolean canRenderInLayer(IBlockState state, BlockRenderLayer layer) {
		return layer == BlockRenderLayer.TRANSLUCENT || layer == BlockRenderLayer.CUTOUT;
	}

	@Override
	public boolean isFullCube(IBlockState state) {
		return false;
	}

	@Override
	public boolean isOpaqueCube(IBlockState state) {
		return false;
	}

	@Override
    public BlockFaceShape getBlockFaceShape(IBlockAccess worldIn, IBlockState state, BlockPos pos, EnumFacing face) {
    	return BlockFaceShape.UNDEFINED;
    }

    @Override
    public int quantityDropped(Random random) {
        return 1;
    }

	@Override
    public Item getItemDropped(IBlockState state, Random rand, int fortune) {
        return Item.getItemFromBlock(this);
    }

	@Override
	public ItemBlock getItemBlock() {
		return ICustomItemBlock.getDefaultItemBlock(this);
	}

}

package thebetweenlands.common.block.container;

import java.util.Locale;
import java.util.Random;

import javax.annotation.Nullable;

import net.minecraft.block.ITileEntityProvider;
import net.minecraft.block.SoundType;
import net.minecraft.block.material.Material;
import net.minecraft.block.properties.IProperty;
import net.minecraft.block.properties.PropertyDirection;
import net.minecraft.block.properties.PropertyEnum;
import net.minecraft.block.state.BlockFaceShape;
import net.minecraft.block.state.BlockStateContainer;
import net.minecraft.block.state.IBlockState;
import net.minecraft.creativetab.CreativeTabs;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.IInventory;
import net.minecraft.inventory.InventoryHelper;
import net.minecraft.item.ItemBlock;
import net.minecraft.item.ItemStack;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.BlockRenderLayer;
import net.minecraft.util.EnumBlockRenderType;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.EnumHand;
import net.minecraft.util.IStringSerializable;
import net.minecraft.util.NonNullList;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.IBlockAccess;
import net.minecraft.world.World;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import net.minecraftforge.items.wrapper.InvWrapper;
import thebetweenlands.common.block.BasicBlock;
import thebetweenlands.common.entity.mobs.EntityBubblerCrab;
import thebetweenlands.common.entity.mobs.EntitySiltCrab;
import thebetweenlands.common.entity.mobs.EntityTermite;
import thebetweenlands.common.item.ItemBlockEnum;
import thebetweenlands.common.item.ItemBlockEnum.IGenericMetaSelector;
import thebetweenlands.common.registries.BlockRegistry.ICustomItemBlock;
import thebetweenlands.common.registries.BlockRegistry.IStateMappedBlock;
import thebetweenlands.common.registries.BlockRegistry.ISubtypeItemBlockModelDefinition;
import thebetweenlands.common.tile.TileEntityLootInventory;
import thebetweenlands.common.tile.TileEntityLootPot;
import thebetweenlands.util.AdvancedStateMap.Builder;

public class BlockLootPot extends BasicBlock implements ITileEntityProvider, ICustomItemBlock, ISubtypeItemBlockModelDefinition, IStateMappedBlock {
	public static final PropertyDirection FACING = PropertyDirection.create("facing", EnumFacing.Plane.HORIZONTAL);
	public static final PropertyEnum<EnumLootPot> VARIANT = PropertyEnum.create("type", EnumLootPot.class);

	public BlockLootPot() {
		this(Material.GLASS);
	}

	public BlockLootPot(Material material) {
		super(material);
		setHardness(0.4f);
		setSoundType(SoundType.GLASS);
		setHarvestLevel("pickaxe", 0);
		this.setDefaultState(this.blockState.getBaseState().withProperty(FACING, EnumFacing.NORTH).withProperty(VARIANT, EnumLootPot.POT_1));
	}

	@Nullable
	public static TileEntityLootPot getTileEntity(IBlockAccess world, BlockPos pos) {
		TileEntity tile = world.getTileEntity(pos);
		if(tile instanceof TileEntityLootPot) {
			return (TileEntityLootPot) tile;
		}
		return null;
	}

	@Override
	public EnumBlockRenderType getRenderType(IBlockState state) {
		return EnumBlockRenderType.MODEL;
	}

	@Override
	public BlockRenderLayer getRenderLayer() {
		return BlockRenderLayer.CUTOUT;
	}

	@Override
	public boolean isOpaqueCube(IBlockState state) {
		return false;
	}

	@Override
	public boolean isBlockNormalCube(IBlockState state) {
		return false;
	}

	@Override
	public TileEntity createNewTileEntity(World worldIn, int meta) {
		return new TileEntityLootPot();
	}

	@Override
	public void getSubBlocks(CreativeTabs itemIn, NonNullList<ItemStack> list) {
		list.add(new ItemStack(this, 1, EnumLootPot.POT_1.getMetadata(EnumFacing.SOUTH)));
		list.add(new ItemStack(this, 1, EnumLootPot.POT_2.getMetadata(EnumFacing.SOUTH)));
		list.add(new ItemStack(this, 1, EnumLootPot.POT_3.getMetadata(EnumFacing.SOUTH)));
	}

	@Override
	public ItemStack getItem(World worldIn, BlockPos pos, IBlockState state) {
		return new ItemStack(this, 1, ((EnumLootPot) state.getValue(VARIANT)).getMetadata(EnumFacing.NORTH));
	}

	@Override
	public IBlockState getStateFromMeta(int meta) {
		return this.getDefaultState().withProperty(VARIANT, EnumLootPot.byMetadata(meta)).withProperty(FACING, EnumFacing.byHorizontalIndex(meta & 3));
	}

	@Override
	public int getMetaFromState(IBlockState state) {
		return ((EnumLootPot) state.getValue(VARIANT)).getMetadata(state.getValue(FACING));
	}

	@Override
	protected BlockStateContainer createBlockState() {
		return new BlockStateContainer(this, new IProperty[]{VARIANT, FACING});
	}

	@Override
	public int quantityDropped(Random random) {
		return 0;
	}

	@Override
	public void onBlockPlacedBy(World worldIn, BlockPos pos, IBlockState state, EntityLivingBase placer, ItemStack stack) {
		int rotation = MathHelper.floor(placer.rotationYaw * 4.0F / 360.0F + 0.5D) & 3;
		state = state.withProperty(FACING, EnumFacing.byHorizontalIndex(rotation));
		state = state.withProperty(VARIANT, EnumLootPot.byMetadata(stack.getItemDamage()));
		worldIn.setBlockState(pos, state, 3);
		TileEntity tile = worldIn.getTileEntity(pos);
		if (tile instanceof TileEntityLootPot) {
			((TileEntityLootPot) tile).setModelRotationOffset(worldIn.rand.nextInt(41) - 20);
			tile.markDirty();
		}
	}

	@Override
	public boolean onBlockActivated(World worldIn, BlockPos pos, IBlockState state, EntityPlayer playerIn, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ) {
		if(!worldIn.isRemote) {
			if (worldIn.getTileEntity(pos) instanceof TileEntityLootPot) {
				TileEntityLootPot tile = (TileEntityLootPot) worldIn.getTileEntity(pos);
				InvWrapper wrapper = new InvWrapper(tile);
				if (!playerIn.getHeldItem(hand).isEmpty()) {
					ItemStack stack = playerIn.getHeldItem(hand);
					ItemStack prevStack = stack.copy();
					for(int i = 0; i < wrapper.getSlots() && !stack.isEmpty(); i++) {
						stack = wrapper.insertItem(i, stack, false);
					}
					if(stack.isEmpty() || stack.getCount() != prevStack.getCount()) {
						if(!playerIn.isCreative()) {
							playerIn.setHeldItem(hand, stack);
						}
						return true;
					}
				} else if(playerIn.isSneaking() && hand == EnumHand.MAIN_HAND) {
					for(int i = 0; i < wrapper.getSlots(); i++) {
						ItemStack extracted = wrapper.extractItem(i, 1, false);
						if(!extracted.isEmpty()) {
							EntityItem item = new EntityItem(worldIn, pos.getX() + 0.5D, pos.getY() + 1.0D, pos.getZ() + 0.5D, extracted);
							item.motionX = item.motionY = item.motionZ = 0D;
							worldIn.spawnEntity(item);
							return true;
						}
					}
				}
			}
		} else {
			return true;
		}
		return false;
	}

	@Override
	public void harvestBlock(World worldIn, EntityPlayer player, BlockPos pos, IBlockState state, @Nullable TileEntity te, @Nullable ItemStack stack) {
		super.harvestBlock(worldIn, player, pos, state, te, stack);
		IInventory tile = (IInventory) worldIn.getTileEntity(pos);
		if (tile != null) {
			((TileEntityLootInventory) tile).fillInventoryWithLoot(player);
		}
	}

	@Override
	public void breakBlock(World worldIn, BlockPos pos, IBlockState state) {
		IInventory tile = (IInventory) worldIn.getTileEntity(pos);
		if (tile != null) {
			InventoryHelper.dropInventoryItems(worldIn, pos, tile);
		}
		super.breakBlock(worldIn, pos, state);
	}

	@Override
	public void onPlayerDestroy(World world, BlockPos pos, IBlockState state) {
		if (!world.isRemote) {
			EntityLivingBase entity = null;
			if (world.rand.nextInt(3) == 0) {
				if (world.getBlockState(pos.up()).getMaterial() != Material.WATER) {
					entity = new EntityTermite(world);
					entity.getEntityAttribute(EntityTermite.SMALL).setBaseValue(1);
				} else {
					if (world.rand.nextBoolean())
						entity = new EntityBubblerCrab(world);
					else
						entity = new EntitySiltCrab(world);
				}
				if (entity != null) {
					entity.setLocationAndAngles(pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, 0.0F, 0.0F);
					world.spawnEntity(entity);
				}
			}
		}
		super.onPlayerDestroy(world, pos, state);
	}

	@Override
	public void onBlockHarvested(World worldIn, BlockPos pos, IBlockState state, EntityPlayer player) {
		super.onBlockHarvested(worldIn, pos, state, player);
	}

	public enum EnumLootPot implements IStringSerializable, IGenericMetaSelector {
		POT_1("1"),
		POT_2("2"),
		POT_3("3");

		private final String name;

		private EnumLootPot(String name) {
			this.name = name.toLowerCase(Locale.ENGLISH);
		}

		public int getMetadata(EnumFacing facing) {
			return facing.getHorizontalIndex() | (this.ordinal() << 2);
		}

		@Override
		public String toString() {
			return this.name;
		}

		public static EnumLootPot byMetadata(int metadata) {
			metadata >>= 2;
			if (metadata < 0 || metadata >= values().length) {
				metadata = 0;
			}
			return values()[metadata];
		}

		@Override
		public String getName() {
			return this.name;
		}

		@Override
		public boolean isMetadataMatching(int meta) {
			return byMetadata(meta) == this;
		}
	}

	@Override
	public int getSubtypeNumber() {
		return EnumLootPot.values().length * 4;
	}

	@Override
	public String getSubtypeName(int meta) {
		return "%s_" + EnumLootPot.byMetadata(meta).getName();
	}

	@Override
	public ItemBlock getItemBlock() {
		return ItemBlockEnum.create(this, EnumLootPot.class);
	}

	@Override
	@SideOnly(Side.CLIENT)
	public void setStateMapper(Builder builder) {
		builder.ignore(VARIANT).withPropertySuffix(VARIANT, e -> e.getName());
	}

	@Override
    public BlockFaceShape getBlockFaceShape(IBlockAccess worldIn, IBlockState state, BlockPos pos, EnumFacing face) {
    	return BlockFaceShape.UNDEFINED;
    }

	@Override
	public boolean isSideSolid(IBlockState base_state, IBlockAccess world, BlockPos pos, EnumFacing side) {
		return false;
	}
}

package thebetweenlands.common.loot;

import java.util.List;
import java.util.Random;

import javax.annotation.Nullable;

import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonObject;
import com.google.gson.JsonSerializationContext;

import net.minecraft.util.JsonUtils;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.storage.loot.LootContext;
import net.minecraft.world.storage.loot.conditions.LootCondition;
import net.minecraft.world.storage.loot.conditions.LootConditionManager;
import thebetweenlands.common.lib.ModInfo;

public class LootConditionFromSharedPool implements LootCondition {
	private final LootCondition[] conditions;
	private final float guaranteedAfterPercentage;
	private final float guaranteedAfter;

	public LootConditionFromSharedPool(LootCondition[] conditions, float guaranteedAfterPercentage, int guaranteedAfter) {
		this.conditions = conditions;
		this.guaranteedAfterPercentage = guaranteedAfterPercentage;
		this.guaranteedAfter = guaranteedAfter;
	}

	@Override
	public boolean testCondition(Random rand, LootContext context) {
		//Returns false if the conditions are met because then the loot entry should
		//not be used in normal non shared loot tables
		return !LootConditionManager.testAllConditions(this.conditions, rand, context);
	}

	public boolean isGuaranteed(float guaranteePercentage, int guaranteeCounter) {
		return (this.guaranteedAfterPercentage >= 0 && this.guaranteedAfterPercentage <= guaranteePercentage) || (this.guaranteedAfter >= 0 && this.guaranteedAfter <= guaranteeCounter);
	}

	/**
	 * Returns whether the loot entry with the specified loot conditions gets items from the shared
	 * pool
	 * @param rand
	 * @param context
	 * @param conditions
	 * @return
	 */
	public static boolean isFromSharedPool(Random rand, LootContext context, List<LootCondition> conditions) {
		return getCondition(rand, context, conditions) != null;
	}

	@Nullable
	public static LootConditionFromSharedPool getCondition(Random rand, LootContext context, List<LootCondition> conditions) {
		for(LootCondition condition : conditions) {
			if(condition instanceof LootConditionFromSharedPool && LootConditionManager.testAllConditions(((LootConditionFromSharedPool) condition).conditions, rand, context)) {
				return (LootConditionFromSharedPool) condition;
			}
		}

		return null;
	}

	public static class Serializer extends LootCondition.Serializer<LootConditionFromSharedPool> {
		public Serializer() {
			super(new ResourceLocation(ModInfo.ID, "from_shared_pool"), LootConditionFromSharedPool.class);
		}

		@Override
		public void serialize(JsonObject json, LootConditionFromSharedPool value, JsonSerializationContext context) {
			if(value.conditions.length > 0) {
				json.add("conditions", context.serialize(value.conditions));
			}
		}

		@Override
		public LootConditionFromSharedPool deserialize(JsonObject json, JsonDeserializationContext context) {
			LootCondition[] conditions;

			if(json.has("conditions")) {
				conditions = (LootCondition[])JsonUtils.deserializeClass(json, "conditions", context, LootCondition[].class);
			} else {
				conditions = new LootCondition[0];
			}

			float guaranteedAfterPercentage = -1;

			if(json.has("guaranteed_after_percentage")) {
				guaranteedAfterPercentage = JsonUtils.getFloat(json, "guaranteed_after_percentage");
			}

			int guaranteedAfter = -1;

			if(json.has("guaranteed_after")) {
				guaranteedAfter = JsonUtils.getInt(json, "guaranteed_after");
			}

			return new LootConditionFromSharedPool(conditions, guaranteedAfterPercentage, guaranteedAfter);
		}
	}
}

package thebetweenlands.common.loot;

import java.util.List;
import java.util.Random;

import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonObject;
import com.google.gson.JsonSerializationContext;

import net.minecraft.util.JsonUtils;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.storage.loot.LootContext;
import net.minecraft.world.storage.loot.conditions.LootCondition;
import net.minecraft.world.storage.loot.conditions.LootConditionManager;
import thebetweenlands.common.lib.ModInfo;

public class LootConditionSharedPool implements LootCondition {
	private final LootCondition[] conditions;

	public LootConditionSharedPool(LootCondition[] conditions) {
		this.conditions = conditions;
	}

	@Override
	public boolean testCondition(Random rand, LootContext context) {
		//Returns false if the conditions are met because then the loot pool should
		//not be used in normal non shared loot tables
		return !LootConditionManager.testAllConditions(this.conditions, rand, context);
	}

	/**
	 * Returns whether the pool with the specified loot conditions belongs to a shared pool
	 * @param rand
	 * @param context
	 * @param conditions
	 * @return
	 */
	public static boolean isSharedPool(Random rand, LootContext context, List<LootCondition> conditions) {
		for(LootCondition condition : conditions) {
			if(condition instanceof LootConditionSharedPool && LootConditionManager.testAllConditions(((LootConditionSharedPool) condition).conditions, rand, context)) {
				return true;
			}
		}

		return false;
	}

	public static class Serializer extends LootCondition.Serializer<LootConditionSharedPool> {
		public Serializer() {
			super(new ResourceLocation(ModInfo.ID, "shared_pool"), LootConditionSharedPool.class);
		}

		@Override
		public void serialize(JsonObject json, LootConditionSharedPool value, JsonSerializationContext context) {
			if(value.conditions.length > 0) {
				json.add("conditions", context.serialize(value.conditions));
			}
		}

		@Override
		public LootConditionSharedPool deserialize(JsonObject json, JsonDeserializationContext context) {
			LootCondition[] conditions;

			if(json.has("conditions")) {
				conditions = (LootCondition[])JsonUtils.deserializeClass(json, "conditions", context, LootCondition[].class);
			} else {
				conditions = new LootCondition[0];
			}

			return new LootConditionSharedPool(conditions);
		}
	}
}

package thebetweenlands.common.loot.shared;

import java.util.Random;

import javax.annotation.Nullable;

import it.unimi.dsi.fastutil.objects.Object2IntMap;
import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import it.unimi.dsi.fastutil.objects.Object2LongMap;
import it.unimi.dsi.fastutil.objects.Object2LongOpenHashMap;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.storage.loot.LootTable;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.loot.ISharedLootPool;
import thebetweenlands.api.loot.LootTableView;
import thebetweenlands.common.world.storage.SharedLootPoolStorage;

public class SharedLootPool implements ISharedLootPool {
	protected ResourceLocation lootTableLocation;

	protected SharedLootPoolStorage storage;

	protected LootTable view;

	protected final Object2IntMap<String> removedItems = new Object2IntOpenHashMap<>();
	protected final Object2LongMap<String> poolSeeds = new Object2LongOpenHashMap<>();
	protected final Object2LongMap<String> entrySeeds = new Object2LongOpenHashMap<>();

	protected long sharedLootSeed;

	protected int guaranteeCounter;

	private SharedLootPool(ResourceLocation lootTableLocation, long seed) {
		this.lootTableLocation = lootTableLocation;
		this.sharedLootSeed = seed;
	}

	public SharedLootPool(ResourceLocation lootTableLocation, long seed, @Nullable SharedLootPoolStorage storage) {
		this(lootTableLocation, seed);
		this.storage = storage;
	}

	public SharedLootPool(NBTTagCompound nbt, @Nullable SharedLootPoolStorage storage) {
		this(null, 0);
		this.storage = storage;
		this.readFromNBT(nbt);
	}

	@Override
	public ResourceLocation getLootTable() {
		return this.lootTableLocation;
	}

	@Override
	public LootTableView getLootTableView() {
		return new SharedLootTableView(this);
	}

	@Override
	public void regenerate() {
		this.removedItems.clear();
		this.entrySeeds.clear();
		this.poolSeeds.clear();
		this.guaranteeCounter = 0;

		this.setLocationDirty();
	}

	@Override
	public void refill() {
		this.removedItems.clear();
		this.guaranteeCounter = 0;

		this.setLocationDirty();
	}

	@Override
	public int getRemovedItems(String pool, int poolRoll, String entry) {
		return this.removedItems.getInt(String.format("%s#%d#%s", pool, poolRoll, entry));
	}

	@Override
	public void setRemovedItems(String pool, int poolRoll, String entry, int count) {
		this.removedItems.put(String.format("%s#%d#%s", pool, poolRoll, entry), count);

		this.setLocationDirty();
	}

	@Override
	public long getLootPoolSeed(Random rand, String pool, int poolRoll) {
		String key = String.format("%s#%d", pool, poolRoll);
		long seed;
		if(this.poolSeeds.containsKey(key)) {
			seed = this.poolSeeds.get(key);
		} else {
			this.poolSeeds.put(key, seed = rand.nextLong());

			this.setLocationDirty();
		}
		return seed;
	}

	@Override
	public long getLootEntrySeed(Random rand, String pool, int poolRoll, String entry) {
		String key = String.format("%s#%d#%s", pool, poolRoll, entry);
		long seed;
		if(this.entrySeeds.containsKey(key)) {
			seed = this.entrySeeds.get(key);
		} else {
			this.entrySeeds.put(key, seed = rand.nextLong());

			this.setLocationDirty();
		}
		return seed;
	}

	@Override
	public int getGuaranteeCounter() {
		return this.guaranteeCounter;
	}

	void incrementGuaranteeCounter() {
		this.guaranteeCounter++;
		this.setLocationDirty();
	}

	@Override
	public float getGuaranteePercentage() {
		int lootInventories = this.storage != null ? this.storage.getSharedLootInventories(this.lootTableLocation) : 0;
		return lootInventories <= 0 ? 1.0F : Math.min((float)this.getGuaranteeCounter() / (float)lootInventories, 1.0F);
	}

	protected void setLocationDirty() {
		if(this.storage != null) {
			this.storage.markDirty();
		}
	}

	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		if(!this.removedItems.isEmpty()) {
			NBTTagCompound removedItemsNbt = new NBTTagCompound();
			for(Object2IntMap.Entry<String> entry : this.removedItems.object2IntEntrySet()) {
				removedItemsNbt.setInteger(entry.getKey(), entry.getIntValue());
			}
			nbt.setTag("removedItems", removedItemsNbt);
		}

		if(!this.poolSeeds.isEmpty()) {
			NBTTagCompound poolSeedsNbt = new NBTTagCompound();
			for(Object2LongMap.Entry<String> entry : this.poolSeeds.object2LongEntrySet()) {
				poolSeedsNbt.setLong(entry.getKey(), entry.getLongValue());
			}
			nbt.setTag("poolSeeds", poolSeedsNbt);
		}

		if(!this.entrySeeds.isEmpty()) {
			NBTTagCompound entrySeedsNbt = new NBTTagCompound();
			for(Object2LongMap.Entry<String> entry : this.entrySeeds.object2LongEntrySet()) {
				entrySeedsNbt.setLong(entry.getKey(), entry.getLongValue());
			}
			nbt.setTag("entrySeeds", entrySeedsNbt);
		}

		if(this.lootTableLocation != null) {
			nbt.setString("lootTable", this.lootTableLocation.toString());
		}

		nbt.setInteger("generatedLootTables", this.guaranteeCounter);

		nbt.setLong("sharedLootSeed", this.sharedLootSeed);

		return nbt;
	}

	public void readFromNBT(NBTTagCompound nbt) {
		this.removedItems.clear();
		NBTTagCompound removedItemsNbt = nbt.getCompoundTag("removedItems");
		for(String key : removedItemsNbt.getKeySet()) {
			this.removedItems.put(key, removedItemsNbt.getInteger(key));
		}

		this.poolSeeds.clear();
		NBTTagCompound poolSeedsNbt = nbt.getCompoundTag("poolSeeds");
		for(String key : poolSeedsNbt.getKeySet()) {
			this.poolSeeds.put(key, poolSeedsNbt.getLong(key));
		}

		this.entrySeeds.clear();
		NBTTagCompound entrySeedsNbt = nbt.getCompoundTag("entrySeeds");
		for(String key : entrySeedsNbt.getKeySet()) {
			this.entrySeeds.put(key, entrySeedsNbt.getLong(key));
		}

		this.lootTableLocation = null;
		if(nbt.hasKey("lootTable", Constants.NBT.TAG_STRING)) {
			this.lootTableLocation = new ResourceLocation(nbt.getString("lootTable"));
		}

		this.guaranteeCounter = nbt.getInteger("generatedLootTables");

		this.sharedLootSeed = nbt.getLong("sharedLootSeed");
	}

	@Override
	public long getLootTableSeed() {
		return this.sharedLootSeed;
	}
}

package thebetweenlands.common.loot.shared;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.Random;

import javax.annotation.Nullable;

import com.google.common.base.Preconditions;

import net.minecraft.item.ItemStack;
import net.minecraft.util.Tuple;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.storage.loot.LootContext;
import net.minecraft.world.storage.loot.LootEntry;
import net.minecraft.world.storage.loot.LootPool;
import net.minecraft.world.storage.loot.LootTable;
import net.minecraft.world.storage.loot.LootTableManager;
import net.minecraft.world.storage.loot.RandomValueRange;
import net.minecraft.world.storage.loot.conditions.LootCondition;
import net.minecraftforge.fml.relauncher.ReflectionHelper;
import thebetweenlands.api.loot.ISharedLootCondition;
import thebetweenlands.api.loot.ISharedLootPool;
import thebetweenlands.api.loot.LootTableView;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.loot.LootConditionFromSharedPool;
import thebetweenlands.common.loot.LootConditionSharedPool;

public class SharedLootTableView extends LootTableView {
	private static final Field f_LootTable_pools;
	private static final Field f_LootPool_lootEntries;
	private static final Field f_LootPool_poolConditions;
	private static final Field f_LootEntry_conditions;

	static {
		f_LootTable_pools = ReflectionHelper.findField(LootTable.class, "pools", "field_186466_c", "c");
		f_LootPool_lootEntries = ReflectionHelper.findField(LootPool.class, "lootEntries", "field_186453_a", "a");
		f_LootPool_poolConditions = ReflectionHelper.findField(LootPool.class, "poolConditions", "field_186454_b", "b");
		f_LootEntry_conditions = ReflectionHelper.findField(LootEntry.class, "conditions", "field_186366_e", "e");
	}

	protected final SharedLootPool primarySharedPool;

	public SharedLootTableView(SharedLootPool primarySharedPool) {
		Preconditions.checkNotNull(primarySharedPool);

		this.primarySharedPool = primarySharedPool;
	}

	@Override
	public List<ItemStack> generateLootForPools(Random rand, LootContext context) {
		return this.generateLootFromSharedPool(rand, context);
	}

	@SuppressWarnings("unchecked")
	protected List<ItemStack> generateLootFromSharedPool(Random rand, LootContext context) {
		List<ItemStack> stacks = new ArrayList<>();

		LootTable lootTable = this.getSharedLootTableInstance(this.primarySharedPool, context.getLootTableManager());

		if(lootTable != null) {
			List<LootPool> pools = new ArrayList<>();
			try {
				pools.addAll((List<LootPool>) f_LootTable_pools.get(lootTable));
			} catch (IllegalArgumentException | IllegalAccessException e) {
				throw new RuntimeException(e);
			}

			List<LootPool> sharedPools = new ArrayList<>();

			Iterator<LootPool> poolsIT = pools.iterator();
			while(poolsIT.hasNext()) {
				LootPool pool = poolsIT.next();

				if(LootConditionSharedPool.isSharedPool(rand, context, this.getPoolConditions(pool, true))) {
					sharedPools.add(pool);

					poolsIT.remove();
				}
			}

			Collections.shuffle(pools, rand);

			this.primarySharedPool.incrementGuaranteeCounter();

			Random sharedPoolRNG;
			long sharedPoolSeed = rand.nextLong(); //Always generate this long so that the generation order doesn't matter
			long setSharedPoolSeed = this.primarySharedPool.getLootTableSeed();
			if(setSharedPoolSeed != 0) {
				sharedPoolRNG = new Random(setSharedPoolSeed);
			} else {
				sharedPoolRNG = new Random(sharedPoolSeed);
			}


			//Generate all items from shared pools
			Map<EntryKey, List<ItemStack>> sharedPoolItems = new HashMap<>();
			for(LootPool pool : sharedPools) {
				this.generateLootForPoolFromSharedPool(sharedPoolItems, sharedPoolRNG, context, pool, true);
			}

			//Generate all items for this individual instance
			Map<EntryKey, List<ItemStack>> poolItems = new HashMap<>();
			for(LootPool pool : pools) {
				this.generateLootForPoolFromSharedPool(poolItems, rand, context, pool, false);
			}

			for(EntryKey lootEntryKey : poolItems.keySet()) {
				List<ItemStack> loot = poolItems.get(lootEntryKey);

				if(lootEntryKey.isNonSharedEntry) {
					stacks.addAll(loot);
					continue;
				}

				Iterator<ItemStack> lootStackIT = loot.iterator();

				lootStackLoop: while(lootStackIT.hasNext()) {
					ItemStack lootStack = lootStackIT.next();

					int availableLootCount = 0;

					sharedStackLoop: for(Entry<EntryKey, List<ItemStack>> sharedLootEntry : sharedPoolItems.entrySet()) {
						EntryKey sharedLootEntryKey = sharedLootEntry.getKey();
						List<ItemStack> sharedLoot = sharedLootEntry.getValue();

						Iterator<ItemStack> sharedLootStackIT = sharedLoot.iterator();

						while(sharedLootStackIT.hasNext()) {
							ItemStack sharedLootStack = sharedLootStackIT.next();

							if(lootStack.isEmpty() && sharedLootStack.isEmpty()) {
								sharedLootStackIT.remove();

								int removedItems = this.primarySharedPool.getRemovedItems(sharedLootEntryKey.pool, sharedLootEntryKey.poolRoll, sharedLootEntryKey.entry);
								this.primarySharedPool.setRemovedItems(sharedLootEntryKey.pool, sharedLootEntryKey.poolRoll, sharedLootEntryKey.entry, removedItems + 1);

								sharedLootStackIT.remove();

								stacks.add(ItemStack.EMPTY);

								//Adding of empty stack is already handled, continue with next loot stack
								continue lootStackLoop;
							} else if(!lootStack.isEmpty() && !sharedLootStack.isEmpty() && lootStack.getItem() == sharedLootStack.getItem()) {
								int additionalAvailableCount = Math.min(lootStack.getCount() - availableLootCount, sharedLootStack.getCount());

								if(additionalAvailableCount > 0) {
									availableLootCount += additionalAvailableCount;

									sharedLootStack.shrink(additionalAvailableCount);

									if(sharedLootStack.isEmpty()) {
										sharedLootStackIT.remove();
									}

									int removedItems = this.primarySharedPool.getRemovedItems(sharedLootEntryKey.pool, sharedLootEntryKey.poolRoll, sharedLootEntryKey.entry);
									this.primarySharedPool.setRemovedItems(sharedLootEntryKey.pool, sharedLootEntryKey.poolRoll, sharedLootEntryKey.entry, removedItems + additionalAvailableCount);

									if(availableLootCount >= lootStack.getCount()) {
										//Loot stack is fully available, can stop checking now
										break sharedStackLoop;
									}
								}
							}
						}
					}

					if(availableLootCount > 0) {
						lootStack.setCount(availableLootCount);

						stacks.add(lootStack.copy());
					}
				}
			}
		}

		return stacks;
	}

	@SuppressWarnings("unchecked")
	protected List<LootCondition> getPoolConditions(LootPool pool, boolean sharedConditions) {
		List<LootCondition> allConditions;
		try {
			allConditions = (List<LootCondition>) f_LootPool_poolConditions.get(pool);
		} catch (IllegalArgumentException | IllegalAccessException e) {
			throw new RuntimeException(e);
		}
		List<LootCondition> conditions = new ArrayList<>();
		for(LootCondition condition : allConditions) {
			if(condition instanceof LootConditionSharedPool == sharedConditions) {
				conditions.add(condition);
			}
		}
		return conditions;
	}

	protected List<LootCondition> getEntryConditions(LootEntry entry, boolean sharedConditions) {
		LootCondition[] allConditions;
		try {
			allConditions = (LootCondition[]) f_LootEntry_conditions.get(entry);
		} catch (IllegalArgumentException | IllegalAccessException e) {
			throw new RuntimeException(e);
		}
		List<LootCondition> conditions = new ArrayList<>();
		for(LootCondition condition : allConditions) {
			if(condition instanceof LootConditionFromSharedPool == sharedConditions) {
				conditions.add(condition);
			}
		}
		return conditions;
	}

	protected boolean testAllConditions(Iterable<LootCondition> conditions, Random rand, LootContext context) {
		if(conditions == null) {
			return true;
		}

		for(LootCondition condition : conditions) {
			if(this.primarySharedPool != null && condition instanceof ISharedLootCondition) {
				if(!((ISharedLootCondition) condition).testCondition(rand, context, this.primarySharedPool)) {
					return false;
				}
			} else {
				if(!condition.testCondition(rand, context)) {
					return false;
				}
			}
		}
		return true;
	}

	protected void generateLootForPoolFromSharedPool(Map<EntryKey, List<ItemStack>> stacks, Random rand, LootContext context, LootPool pool, boolean isSharedPool) {
		if(context.addLootTable(this)) {
			this.generateLootFromSharedPool(stacks, rand, context, pool, isSharedPool);

			context.removeLootTable(this);
		} else {
			TheBetweenlands.logger.warn("Detected infinite loop in loot tables");
		}
	}

	protected void generateLootFromSharedPool(Map<EntryKey, List<ItemStack>> stacks, Random rand, LootContext context, LootPool pool, boolean isSharedPool) {
		List<LootCondition> poolConditions = this.getPoolConditions(pool, false);

		RandomValueRange rolls = pool.getRolls();
		RandomValueRange bonusRolls = pool.getBonusRolls();

		if(this.testAllConditions(poolConditions, rand, context)) {
			Random poolRand = rand;
			if(isSharedPool) {
				//Count must be consistently the same for the same shared pool
				poolRand = new Random(this.primarySharedPool.getLootPoolSeed(rand, pool.getName(), -1));
			}
			int count = rolls.generateInt(poolRand) + MathHelper.floor(bonusRolls.generateFloat(poolRand) * context.getLuck());

			for(int i = 0; i < count; ++i) {
				this.createLootRollFromSharedPool(stacks, rand, context, pool, isSharedPool, i);
			}
		}
	}

	@SuppressWarnings("unchecked")
	protected boolean createLootRollFromSharedPool(Map<EntryKey, List<ItemStack>> stacks, Random rand, LootContext context, LootPool pool, boolean isSharedPool, int poolRoll) {
		int totalWeights = 0;

		List<LootEntry> lootEntries;
		try {
			lootEntries = (List<LootEntry>) f_LootPool_lootEntries.get(pool);
		} catch (IllegalArgumentException | IllegalAccessException e) {
			throw new RuntimeException(e);
		}

		List<Tuple<LootEntry, List<ItemStack>>> potentialLootEntries = new ArrayList<>();

		List<Tuple<LootEntry, List<ItemStack>>> guaranteedEntries = new ArrayList<>();

		final int guaranteeCounter = this.primarySharedPool.getGuaranteeCounter();
		final float guaranteePercentage = this.primarySharedPool.getGuaranteePercentage();

		for(LootEntry lootEntry : lootEntries) {
			LootConditionFromSharedPool fromSharedPoolCondition = LootConditionFromSharedPool.getCondition(rand, context, this.getEntryConditions(lootEntry, true));

			boolean isGuaranteed = !isSharedPool && fromSharedPoolCondition != null && fromSharedPoolCondition.isGuaranteed(guaranteePercentage, guaranteeCounter);

			if(isGuaranteed || this.testAllConditions(this.getEntryConditions(lootEntry, false), rand, context)) {
				int weight = lootEntry.getEffectiveWeight(context.getLuck());

				if(isGuaranteed || weight > 0) {
					List<ItemStack> generatedStacks = new ArrayList<>();

					Random entryRand = rand;
					if(isSharedPool) {
						//Generated loot must be consistently the same for the same shared pool, roll and entry
						entryRand = new Random(this.primarySharedPool.getLootEntrySeed(rand, pool.getName(), poolRoll, lootEntry.getEntryName()));
					}
					lootEntry.addLoot(generatedStacks, entryRand, context);

					if(isGuaranteed) {
						guaranteedEntries.add(new Tuple<>(lootEntry, generatedStacks));
					} else {
						potentialLootEntries.add(new Tuple<>(lootEntry, generatedStacks));

						totalWeights += weight;
					}
				}
			}
		}

		List<Tuple<LootEntry, List<ItemStack>>> validEntries = new ArrayList<>();

		if(!guaranteedEntries.isEmpty()) {
			validEntries.addAll(guaranteedEntries);
		} else {
			if(totalWeights != 0 && !potentialLootEntries.isEmpty()) {
				Random poolRand = rand;
				if(isSharedPool) {
					//randomWeight must be consistently the same for the same shared pool and roll
					poolRand = new Random(this.primarySharedPool.getLootPoolSeed(rand, pool.getName(), poolRoll));
				}
				int randomWeight = poolRand.nextInt(totalWeights);

				for(Tuple<LootEntry, List<ItemStack>> potentialEntry : potentialLootEntries) {
					randomWeight -= potentialEntry.getFirst().getEffectiveWeight(context.getLuck());

					if(randomWeight < 0) {
						validEntries.add(potentialEntry);
						break;
					}
				}
			}
		}

		if(!validEntries.isEmpty()) {
			for(Tuple<LootEntry, List<ItemStack>> validEntry : validEntries) {
				LootEntry lootEntry = validEntry.getFirst();
				List<ItemStack> loot = validEntry.getSecond();

				boolean isLootEntryStillAvailable = true;

				if(isSharedPool) {
					int removedItems = this.primarySharedPool.getRemovedItems(pool.getName(), poolRoll, lootEntry.getEntryName());

					if(!loot.isEmpty()) {
						//Not empty entry

						this.removeRandomItems(rand, loot, removedItems);

						if(!loot.isEmpty()) {
							int count = 0;
							for(ItemStack stack : loot) {
								count += stack.getCount();
							}

							if(count > 0) {
								isLootEntryStillAvailable = true;
							} else {
								isLootEntryStillAvailable = false;
							}
						} else {
							isLootEntryStillAvailable = false;
						}
					} else {
						//Empty entry

						if(removedItems <= 0) {
							isLootEntryStillAvailable = true;
						} else {
							isLootEntryStillAvailable = false;
						}
					}
				}

				if(isLootEntryStillAvailable) {
					final EntryKey key;

					if(isSharedPool) {
						key = new EntryKey(pool.getName(), poolRoll, lootEntry.getEntryName(), false);
					} else {
						key = new EntryKey(pool.getName(), poolRoll, lootEntry.getEntryName(), !LootConditionFromSharedPool.isFromSharedPool(rand, context, this.getEntryConditions(lootEntry, true)));
					}

					List<ItemStack> entryStacks = stacks.get(key);
					if(entryStacks == null) {
						stacks.put(key, entryStacks = new ArrayList<>());
					}

					entryStacks.addAll(loot);

					return true;
				}
			}
		}

		return false;
	}

	protected int removeRandomItems(Random rand, List<ItemStack> loot, int count) {
		if(loot.isEmpty()) {
			return 0;
		}

		for(int i = 0; i < count; i++) {
			int randStack = rand.nextInt(loot.size());
			ItemStack stack = loot.get(randStack);

			stack.shrink(1);

			if(stack.isEmpty()) {
				loot.remove(randStack);
			}

			if(loot.isEmpty()) {
				return i;
			}
		}

		return count;
	}

	@Nullable
	protected LootTable getSharedLootTableInstance(ISharedLootPool pool, LootTableManager manager) {
		if(pool.getLootTable() != null) {
			return manager.getLootTableFromLocation(pool.getLootTable());
		}
		return null;
	}

	protected static class EntryKey {
		protected final String pool;
		protected final String entry;

		protected final int poolRoll;
		protected final boolean isNonSharedEntry;

		private final int hashCode;

		protected EntryKey(String pool, int poolRoll, String entry, boolean isNonSharedEntry) {
			this.pool = pool;
			this.poolRoll = poolRoll;
			this.entry = entry;
			this.isNonSharedEntry = isNonSharedEntry;

			final int prime = 31;
			int hashCode = 1;
			hashCode = prime * hashCode + this.entry.hashCode();
			hashCode = prime * hashCode + this.pool.hashCode();
			this.hashCode = hashCode;
		}

		@Override
		public int hashCode() {
			return this.hashCode;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (this.getClass() != obj.getClass())
				return false;
			EntryKey other = (EntryKey) obj;
			return other.entry.equals(this.entry) && other.pool.equals(this.pool);
		}
	}
}

package thebetweenlands.common.registries;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

import javax.annotation.Nullable;

import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;

import net.minecraft.util.ResourceLocation;
import thebetweenlands.api.storage.IDeferredStorageOperation;
import thebetweenlands.api.storage.ILocalStorage;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.lib.ModInfo;
import thebetweenlands.common.world.storage.SharedLootPoolStorage;
import thebetweenlands.common.world.storage.location.LocationChiromawMatriarchNest;
import thebetweenlands.common.world.storage.location.LocationCragrockTower;
import thebetweenlands.common.world.storage.location.LocationGuarded;
import thebetweenlands.common.world.storage.location.LocationPortal;
import thebetweenlands.common.world.storage.location.LocationSludgeWormDungeon;
import thebetweenlands.common.world.storage.location.LocationSpiritTree;
import thebetweenlands.common.world.storage.location.LocationStorage;
import thebetweenlands.common.world.storage.location.LocationTokenBucket;
import thebetweenlands.common.world.storage.operation.DeferredLinkOperation;

public class StorageRegistry {
	private static final BiMap<ResourceLocation, Class<? extends ILocalStorage>> STORAGE_MAP = HashBiMap.create();
	private static final Map<ResourceLocation, Factory<?>> FACTORIES = new HashMap<>();

	private static final BiMap<ResourceLocation, Class<? extends IDeferredStorageOperation>> DEFERRED_MAP = HashBiMap.create();
	private static final Map<ResourceLocation, Supplier<? extends IDeferredStorageOperation>> DEFERRED_FACTORIES = new HashMap<>();

	public static interface Factory<T extends ILocalStorage> {
		public T create(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region);
	}

	public static void preInit() {
		register(new ResourceLocation(ModInfo.ID, "shared_loot_pool_storage"), SharedLootPoolStorage.class, SharedLootPoolStorage::new);
		register(new ResourceLocation(ModInfo.ID, "location_storage"), LocationStorage.class, LocationStorage::new);
		register(new ResourceLocation(ModInfo.ID, "cragrock_tower"), LocationCragrockTower.class, LocationCragrockTower::new);
		register(new ResourceLocation(ModInfo.ID, "location_guarded"), LocationGuarded.class, LocationGuarded::new);
		register(new ResourceLocation(ModInfo.ID, "portal"), LocationPortal.class, LocationPortal::new);
		register(new ResourceLocation(ModInfo.ID, "spirit_tree"), LocationSpiritTree.class, LocationSpiritTree::new);
		register(new ResourceLocation(ModInfo.ID, "sludge_worm_dungeon"), LocationSludgeWormDungeon.class, LocationSludgeWormDungeon::new);
		register(new ResourceLocation(ModInfo.ID, "chiromaw_matriarch_nest"), LocationChiromawMatriarchNest.class, LocationChiromawMatriarchNest::new);
		register(new ResourceLocation(ModInfo.ID, "token_bucket"), LocationTokenBucket.class, LocationTokenBucket::new);

		register(new ResourceLocation(ModInfo.ID, "deferred_link"), DeferredLinkOperation.class, DeferredLinkOperation::new);
	}

	/**
	 * Registers a local storage
	 * @param cls
	 * @param id
	 * @param factory
	 */
	public static <T extends ILocalStorage> void register(ResourceLocation id, Class<T> cls, Factory<T> factory) {
		STORAGE_MAP.put(id, cls);
		FACTORIES.put(id, factory);
	}

	/**
	 * Returns the local storage class for the specified ID
	 * @param type
	 * @return
	 */
	public static Class<? extends ILocalStorage> getStorageType(ResourceLocation id) {
		return STORAGE_MAP.get(id);
	}

	/**
	 * Returns the factory for the specified id
	 * @param id
	 * @return
	 */
	public static Factory<? extends ILocalStorage> getStorageFactory(ResourceLocation id) {
		return FACTORIES.get(id);
	}

	/**
	 * Returns the ID of a local storage class
	 * @param storage
	 * @return
	 */
	public static ResourceLocation getStorageId(Class<? extends ILocalStorage> storage) {
		return STORAGE_MAP.inverse().get(storage);
	}

	/**
	 * Registers a deferred storage operation
	 * @param cls
	 * @param id
	 * @param factory
	 */
	public static <T extends IDeferredStorageOperation> void register(ResourceLocation id, Class<T> cls, Supplier<T> factory) {
		DEFERRED_MAP.put(id, cls);
		DEFERRED_FACTORIES.put(id, factory);
	}

	/**
	 * Returns the local storage class for the specified ID
	 * @param type
	 * @return
	 */
	public static Class<? extends IDeferredStorageOperation> getDeferredOperationType(ResourceLocation id) {
		return DEFERRED_MAP.get(id);
	}

	/**
	 * Returns the factory for the specified id
	 * @param id
	 * @return
	 */
	public static Supplier<? extends IDeferredStorageOperation> getDeferredOperationFactory(ResourceLocation id) {
		return DEFERRED_FACTORIES.get(id);
	}

	/**
	 * Returns the ID of a deferred storage operation class
	 * @param operation
	 * @return
	 */
	public static ResourceLocation getDeferredOperationId(Class<? extends IDeferredStorageOperation> operation) {
		return DEFERRED_MAP.inverse().get(operation);
	}
}

package thebetweenlands.common.tile;

import java.util.function.BiFunction;

import javax.annotation.Nonnull;

import mcp.MethodsReturnNonnullByDefault;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.ISidedInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.NonNullList;
import net.minecraft.util.text.ITextComponent;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.items.CapabilityItemHandler;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.ItemStackHandler;
import net.minecraftforge.items.wrapper.InvWrapper;
import net.minecraftforge.items.wrapper.SidedInvWrapper;

public class TileEntityBasicInventory extends TileEntity implements ISidedInventory {
	private static class ISHSidedInvWrapper extends SidedInvWrapper {
		private final ItemStackHandler handler;

		public ISHSidedInvWrapper(ISidedInventory inv, EnumFacing side, ItemStackHandler handler) {
			super(inv, side);
			this.handler = handler;
		}

		@Override
		public int getSlotLimit(int slot) {
			return Math.min(super.getSlotLimit(slot), this.handler.getSlotLimit(slot));
		}
	}

	protected static final BiFunction<TileEntityBasicInventory, NonNullList<ItemStack>, ItemStackHandler> DEFAULT_HANDLER = (te, inv) -> new ItemStackHandler(inv) {
		@Override
		public void setSize(int size) {
			if(size != inv.size()) {
				throw new UnsupportedOperationException("Can't resize this inventory");
			}
		}

		@Override
		protected void onContentsChanged(int slot) {
			// Don't mark dirty while loading chunk!
			if(te.hasWorld()) {
				te.markDirty();
			}
		}
	};

	private final String name;
	protected NonNullList<ItemStack> inventory;
	protected final ItemStackHandler inventoryHandler;

	private final IItemHandler handlerUp;
	private final IItemHandler handlerDown;
	private final IItemHandler handlerNorth;
	private final IItemHandler handlerSouth;
	private final IItemHandler handlerEast;
	private final IItemHandler handlerWest;
	private final IItemHandler handlerNull;

	public TileEntityBasicInventory(int invSize, String name) {
		this(name, NonNullList.withSize(invSize, ItemStack.EMPTY), DEFAULT_HANDLER);
	}

	public TileEntityBasicInventory(String name, NonNullList<ItemStack> inventory, BiFunction<TileEntityBasicInventory, NonNullList<ItemStack>, ItemStackHandler> handler) {
		this.inventoryHandler = handler.apply(this, inventory);
		this.inventory = inventory;
		this.name = name;

		this.handlerUp = new ISHSidedInvWrapper(this, EnumFacing.UP, this.inventoryHandler);
		this.handlerDown = new ISHSidedInvWrapper(this, EnumFacing.DOWN, this.inventoryHandler);
		this.handlerNorth = new ISHSidedInvWrapper(this, EnumFacing.NORTH, this.inventoryHandler);
		this.handlerSouth = new ISHSidedInvWrapper(this, EnumFacing.SOUTH, this.inventoryHandler);
		this.handlerEast = new ISHSidedInvWrapper(this, EnumFacing.EAST, this.inventoryHandler);
		this.handlerWest = new ISHSidedInvWrapper(this, EnumFacing.WEST, this.inventoryHandler);
		this.handlerNull = new InvWrapper(this) {
			@Override
			public int getSlotLimit(int slot) {
				return Math.min(super.getSlotLimit(slot), TileEntityBasicInventory.this.inventoryHandler.getSlotLimit(slot));
			}
		};
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);
		this.readInventoryNBT(nbt);
	}

	/**
	 * Reads the inventory from NBT
	 * @param nbt
	 */
	protected void readInventoryNBT(NBTTagCompound nbt) {
		this.clear();
		if(nbt.hasKey("Inventory", Constants.NBT.TAG_COMPOUND)) {
			this.inventoryHandler.deserializeNBT(nbt.getCompoundTag("Inventory"));
		}
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		super.writeToNBT(nbt);
		this.writeInventoryNBT(nbt);
		return nbt;
	}

	/**
	 * Writes the inventory to NBT
	 * @param nbt
	 */
	protected void writeInventoryNBT(NBTTagCompound nbt) {
		NBTTagCompound inventoryNbt = this.inventoryHandler.serializeNBT();
		nbt.setTag("Inventory", inventoryNbt);
	}

	@Override
	public int getSizeInventory() {
		return this.inventoryHandler.getSlots();
	}

	@Override
	public boolean isEmpty() {
		return inventory.isEmpty();
	}

	@Override
	@MethodsReturnNonnullByDefault
	public ItemStack getStackInSlot(int slot) {
		this.accessSlot(slot);
		return this.inventoryHandler.getStackInSlot(slot);
	}

	@Override
	public int getInventoryStackLimit() {
		return 64;
	}

	@Override
	public boolean isUsableByPlayer(EntityPlayer player) {
		if(this.world.getTileEntity(this.pos) != this) {
			return false;
		} else {
			return player.getDistanceSq((double)this.pos.getX() + 0.5D, (double)this.pos.getY() + 0.5D, (double)this.pos.getZ() + 0.5D) <= 64.0D;
		}
	}

	@Override
	public String getName() {
		return name;
	}

	@Override
	public boolean hasCustomName() {
		return false;
	}

    @Override
    public ITextComponent getDisplayName() {
        return this.hasCustomName() ? new TextComponentString(this.getName()) : new TextComponentTranslation(this.getName());
    }

	@Override
	public int[] getSlotsForFace(EnumFacing side) {
		int[] slots = new int[getSizeInventory()];
		for (int i = 0; i < slots.length; i++) {
			slots[i] = i;
		}

		return slots;
	}

	@Override
	public boolean isItemValidForSlot(int slot, ItemStack stack) {
		return true;
	}

	@Override
	public int getField(int id) {
		return 0;
	}

	@Override
	public void setField(int id, int value) {}

	@Override
	public int getFieldCount() {
		return 0;
	}

	@Override
	public boolean canInsertItem(int slot, ItemStack stack, EnumFacing side) {
		this.accessSlot(slot);
		return isItemValidForSlot(slot, stack) && this.getStackInSlot(slot).getCount() + stack.getCount() <= this.inventoryHandler.getSlotLimit(slot);
	}

	@Override
	public boolean canExtractItem(int slot, ItemStack stack, EnumFacing side) {
		this.accessSlot(slot);
		return true;
	}

	@Override
	public void openInventory(EntityPlayer player) {}

	@Override
	public void closeInventory(EntityPlayer player) {}

	@Override
	public ItemStack decrStackSize(int index, int count) {
		this.accessSlot(index);
		return this.inventoryHandler.extractItem(index, count, false);
	}

	@Override
	public ItemStack removeStackFromSlot(int index) {
		this.accessSlot(index);
		return this.inventoryHandler.extractItem(index, !this.inventoryHandler.getStackInSlot(index).isEmpty() ? this.inventoryHandler.getStackInSlot(index).getCount() : 0, false);
	}

	@Override
	public void setInventorySlotContents(int index, @Nonnull ItemStack stack) {
		this.accessSlot(index);
		this.inventoryHandler.setStackInSlot(index, stack);
	}

	@Override
	public void clear() {
		for(int i = 0; i < this.inventoryHandler.getSlots(); i++) {
			this.inventoryHandler.setStackInSlot(i, ItemStack.EMPTY);
		}
	}

	/**
	 * Called before a slot is accessed
	 * @param slot
	 */
	protected void accessSlot(int slot) {

	}

	@Override
	public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
		return capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY || super.hasCapability(capability, facing);
	}

	@SuppressWarnings("unchecked")
	@Override
	public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
		if(capability == CapabilityItemHandler.ITEM_HANDLER_CAPABILITY) {
			if (facing == null) {
				return (T) handlerNull;
			}
			switch (facing) {
				case DOWN:
					return (T) this.handlerDown;
				case UP:
					return (T) this.handlerUp;
				case NORTH:
					return (T) this.handlerNorth;
				case SOUTH:
					return (T) this.handlerSouth;
				case WEST:
					return (T) this.handlerWest;
				case EAST:
					return (T) this.handlerEast;
			}
		}
		return super.getCapability(capability, facing);
	}
}

package thebetweenlands.common.tile;

import javax.annotation.Nullable;

import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.tileentity.TileEntityChest;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.loot.ISharedLootContainer;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.world.storage.SharedLootPoolStorage;

public class TileEntityChestBetweenlands extends TileEntityChest implements ISharedLootContainer {
	protected StorageID storageId;
	protected boolean isSharedLootTable;

	@Override
	public boolean shouldRefresh(World world, BlockPos pos, IBlockState oldState, IBlockState newSate) {
		//Use vanilla behaviour to prevent inventory from resetting when creating double chest
		return oldState.getBlock() != newSate.getBlock();
	}

	@Override
	public AxisAlignedBB getRenderBoundingBox() {
		return new AxisAlignedBB(pos.add(-1, 0, -1), pos.add(2, 2, 2));
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound compound) {
		return super.writeToNBT(compound);
	}

	@Override
	public void readFromNBT(NBTTagCompound compound) {
		super.readFromNBT(compound);
	}

	@Override
	protected boolean checkLootAndRead(NBTTagCompound compound) {
		this.isSharedLootTable = false;

		if(super.checkLootAndRead(compound)) {
			this.isSharedLootTable = compound.getBoolean("SharedLootTable");

			if(compound.hasKey("StorageID", Constants.NBT.TAG_COMPOUND)) {
				this.storageId = StorageID.readFromNBT(compound.getCompoundTag("StorageID"));
			}

			return true;
		}

		return false;
	}

	@Override
	protected boolean checkLootAndWrite(NBTTagCompound compound) {
		if(super.checkLootAndWrite(compound)) {
			compound.setBoolean("SharedLootTable", this.isSharedLootTable);

			if(this.storageId != null) {
				compound.setTag("StorageID", this.storageId.writeToNBT(new NBTTagCompound()));
			}

			return true;
		}

		return false;
	}

	@Override
	public boolean isSharedLootTable() {
		return this.isSharedLootTable;
	}

	@Override
	public void fillWithLoot(@Nullable EntityPlayer player) {
		this.fillInventoryWithLoot(player);
	}

	@Override
	public boolean fillInventoryWithLoot(@Nullable EntityPlayer player) {
		return TileEntityLootInventory.fillInventoryWithLoot(this.world, this, player, this.lootTableSeed);
	}

	@Override
	public void removeLootTable() {
		if(this.lootTable != null) {
			this.lootTable = null;
			this.markDirty();
		}
	}

	@Override
	public void setLootTable(ResourceLocation lootTable, long lootTableSeed) {
		super.setLootTable(lootTable, lootTableSeed);
		this.isSharedLootTable = false;
		this.markDirty();
	}

	@Override
	public void setSharedLootTable(SharedLootPoolStorage storage, ResourceLocation lootTable, long lootTableSeed) {
		if(!lootTable.equals(this.lootTable)) {
			storage.registerSharedLootInventory(this.pos, lootTable);
		}
		this.storageId = storage.getID();
		this.lootTable = lootTable;
		this.lootTableSeed = lootTableSeed;
		this.isSharedLootTable = true;
		this.markDirty();
	}

	@Override
	public StorageID getSharedLootPoolStorageID() {
		return this.storageId;
	}
}

package thebetweenlands.common.tile;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

import javax.annotation.Nullable;

import net.minecraft.block.material.Material;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLiving;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.network.NetworkManager;
import net.minecraft.network.play.server.SPacketUpdateTileEntity;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.ITickable;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.BlockPos.MutableBlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import net.minecraft.world.biome.Biome;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.entity.spawning.ICustomSpawnEntriesProvider;
import thebetweenlands.api.entity.spawning.ICustomSpawnEntry;
import thebetweenlands.common.entity.mobs.EntityBubblerCrab;
import thebetweenlands.common.entity.mobs.EntitySiltCrab;
import thebetweenlands.common.item.misc.ItemMisc.EnumItemMisc;
import thebetweenlands.common.item.misc.ItemMob;
import thebetweenlands.common.lib.ModInfo;
import thebetweenlands.common.registries.AdvancementCriterionRegistry;
import thebetweenlands.common.registries.BlockRegistry;
import thebetweenlands.common.registries.ItemRegistry;
import thebetweenlands.common.world.storage.location.TokenBucket;

public class TileEntityCrabPot extends TileEntityBasicInventory implements ITickable {
	public static final ResourceLocation CRAB_POT_SPAWNING_TOKEN_BUCKET_ID = new ResourceLocation(ModInfo.ID, "crab_pot_spawning");

	private boolean active;
	public int fallCounter = 16;
	public int fallCounterPrev;
	private int horizontalIndex = 0;
	public int prevAnimationTicks;
	public int animationTicks;
	public boolean animate = false;
	private EntityPlayer placer;
	private UUID placerUUID;
	private int catchTimer;
	private int catchTimerMax;

	private TokenBucket tokenBucket = new TokenBucket(CRAB_POT_SPAWNING_TOKEN_BUCKET_ID, 64, 48, 64, 1, 4, 0.99D, 1);

	public TileEntityCrabPot() {
		super(1, "container.bl.crab_pot");
	}

	@Override
	public boolean shouldRefresh(World world, BlockPos pos, IBlockState oldState, IBlockState newState) {
		return oldState.getBlock() != newState.getBlock();
	}

	@Override
	public void setWorld(World worldIn) {
		super.setWorld(worldIn);

		this.updatePlacerFromUUID();

		this.tokenBucket.setWorld(this.world);
	}

	@Override
	public void setPos(BlockPos posIn) {
		super.setPos(posIn);

		this.tokenBucket.setPos(posIn);
	}

	@Override
	public void update() {
		if (world.isRemote) {
			fallCounterPrev = fallCounter;
			if (!hasBaitItem()) {
				if (fallCounter > 0) {
					fallCounter--;
				}
				if (fallCounter <= 0) {
					fallCounter = 0;
				}
			}
			if (hasBaitItem() && fallCounter != 32) {
				fallCounter = 32;
			}

			prevAnimationTicks = animationTicks;

			if(animate) {
				animationTicks++;
			}
			if(!animate && animationTicks > 0) {
				animationTicks = 0;
			}
		}

		if(!world.isRemote) {
			if(this.catchTimerMax == 0) {
				this.resetCatchTimer();
			}

			// because the player is always null unless the world is loaded but block NBT is loaded before grrrrr
			if(placerUUID != null && getPlacer() == null && world.getTotalWorldTime() % 20 == 0) {
				if(updatePlacerFromUUID()) {
					markForUpdate();
				}
			}

			if(hasBaitItem() && !active) {
				active = true;
				markDirty();
			}

			if(!hasBaitItem() && active) {
				active = false;
				markDirty();
			}

			if(active && this.getStackInSlot(0).getItem() instanceof ItemMob == false) {
				if(world.getTotalWorldTime() % 20 == 0) {
					EntitySiltCrab entity = null;

					this.updateCatchTimer();

					int remainingCatchTicks = this.getRemainingCatchTicks();

					if(remainingCatchTicks <= 0 && this.world.getGameRules().getBoolean("doMobSpawning") && this.world.getClosestPlayer(this.pos.getX() + 0.5f, this.pos.getY() + 0.5f, this.pos.getZ() + 0.5f, 32.0D, false) == null && this.world.canSeeSky(this.pos.up())) {
						int checks = 64;
						int spawnableBlocks = 0;

						Map<Biome, Boolean> spawnableBiomes = new HashMap<>();

						MutableBlockPos checkPos = new MutableBlockPos();
						for(int i = 0; i < checks; i++) {
							checkPos.setPos(this.pos.getX() + this.world.rand.nextInt(13) - 6, this.pos.getY() + this.world.rand.nextInt(5) - 1, this.pos.getZ() + this.world.rand.nextInt(13) - 6);

							if(this.world.getBlockState(checkPos).getMaterial() == Material.WATER && this.world.canSeeSky(checkPos)) {
								Biome biome = this.world.getBiome(checkPos);

								if(spawnableBiomes.containsKey(biome)) {
									if(spawnableBiomes.get(biome)) {
										spawnableBlocks++;
									}
								} else {
									boolean biomeSpawnable = false;

									if(biome instanceof ICustomSpawnEntriesProvider) {
										for(ICustomSpawnEntry spawnEntry : ((ICustomSpawnEntriesProvider) biome).getCustomSpawnEntries()) {
											if(EntitySiltCrab.class.isAssignableFrom(spawnEntry.getEntityType())) {
												biomeSpawnable = true;
												break;
											}
										}
									}

									spawnableBiomes.put(biome, biomeSpawnable);

									if(biomeSpawnable) {
										spawnableBlocks++;
									}
								}
							}
						}

						float probability = Math.min(1, (float)Math.pow((float)spawnableBlocks / (float)checks * 2.0f, 2.0f) * 2.0f);

						if(this.world.rand.nextFloat() <= probability) {
							entity = this.createRandomCatch(spawnableBiomes.entrySet().stream().filter(e -> e.getValue()).map(e -> e.getKey()).collect(Collectors.toSet()));
						}

						this.resetCatchTimer();
					}

					if(entity == null) {
						lureCloseCrab();
						entity = this.checkCatch();
					}

					if(entity != null) {
						ItemMob itemMob = entity.getCrabPotItem();

						if(itemMob != null) {
							ItemStack stack = itemMob.capture(entity);

							if(!stack.isEmpty()) {
								entity.setDropItemsWhenDead(false);
								entity.setDead();

								setInventorySlotContents(0, stack);

								EntityPlayer placer = getPlacer();
								if(placer == null) {
									updatePlacerFromUUID();
									placer = getPlacer();
								}

								markDirty();

								if((hasSiltCrab() || hasBubblerCrab()) && placer instanceof EntityPlayerMP) {
									AdvancementCriterionRegistry.CRAB_POT.trigger((EntityPlayerMP) placer);
								}
							}
						}
					}

					//Mark dirty without markForUpdate()
					super.markDirty();
				}
			} else {
				this.resetCatchTimer();
			}

			if (getWorld().getBlockState(pos.down()).getBlock() != BlockRegistry.CRAB_POT_FILTER && animate) {
				animate = false;
				markForUpdate();
			}
		}
	}

	public void resetCatchTimer() {
		this.catchTimerMax = 24000 + this.world.rand.nextInt(36000);
		this.catchTimer = 0;
	}

	private void updateCatchTimer() {
		long increment = this.tokenBucket.consume();
		this.catchTimer = MathHelper.clamp(this.catchTimer + (int)increment, 0, this.catchTimerMax);
	}

	public int getRemainingCatchTicks() {
		return MathHelper.clamp(this.catchTimerMax - this.catchTimer, 0, this.catchTimerMax);
	}

	private boolean updatePlacerFromUUID() {
		if(placerUUID != null) {
			EntityPlayer player = this.world.getPlayerEntityByUUID(placerUUID);
			if(player != null && player != getPlacer()) {
				setPlacer(player);
				return true;
			}
		}
		return false;
	}

	@Nullable
	private EntitySiltCrab createRandomCatch(Set<Biome> biomes) {
		EntitySiltCrab crab = null;
		switch(this.world.rand.nextInt(2)) {
		case 0:
			crab = new EntitySiltCrab(this.world);
			break;
		case 1:
			crab = new EntityBubblerCrab(this.world);
			break;
		}
		if(crab != null) {
			crab.randomizeSiltCrabProperties();
		}
		return crab;
	}

	@Nullable
	private EntitySiltCrab checkCatch() {
		List<EntityLiving> list = getWorld().getEntitiesWithinAABB(EntityLiving.class, new AxisAlignedBB(pos.up()).grow(-0.25D, 0F, -0.25D), e -> e instanceof EntitySiltCrab);
		if (!list.isEmpty()) {
			return (EntitySiltCrab) list.get(this.world.rand.nextInt(list.size()));
		}
		return null;
	}

	public void lureCloseCrab() {
		List<EntityLiving> list = getWorld().getEntitiesWithinAABB(EntityLiving.class, extendRangeBox(), e -> e.isInWater() && e instanceof EntitySiltCrab);
		if (!list.isEmpty()) {
			((EntitySiltCrab) list.get(this.world.rand.nextInt(list.size()))).lureToCrabPot(this.pos);
		}
	}

	public AxisAlignedBB extendRangeBox() {
		return  new AxisAlignedBB(pos).grow(12D, 5D, 12D);
	}

	public boolean hasBaitItem() {
