		readFromNBT(packet.getNbtCompound());
	}

	@Override
	public NBTTagCompound getUpdateTag() {
		return writeToNBT(new NBTTagCompound());
	}

	private EntityPlayer getPlacer() {
		return this.placer;
	}

	public void setPlacer(EntityPlayer player) {
		this.placer = player;
	}

	@Override
