		}
		for(int i = 0; i < 5; i++) {
			this.towerLocation.setLevelBlockadeBlocks(i, levelBlockades[i]);
		}
		this.towerLocation.setDirty(true);
		this.worldStorage.getLocalStorageHandler().addLocalStorage(this.towerLocation);

		return true;
	}
