import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.network.clientbound.MessageSyncLocalStorageData;
import thebetweenlands.common.registries.StorageRegistry;

public class LocalStorageHandlerImpl implements ILocalStorageHandler {
	private final IWorldStorage worldStorage;
	private final World world;
	private final File localStorageDir;

	private final Map<StorageID, ILocalStorage> localStorage = new HashMap<>();
	private final List<ILocalStorage> tickableLocalStorage = new ArrayList<>();
	private final List<ILocalStorage> pendingUnreferencedStorages = new ArrayList<>();

	private final TObjectLongMap<LocalRegionData> pendingUnreferencedRegions = new TObjectLongHashMap<>();

	private final LocalRegionCache regionCache;

	private final LocalStorageSaveHandler saveHandler = new LocalStorageSaveHandler();

	public LocalStorageHandlerImpl(IWorldStorage worldStorage) {
		this.worldStorage = worldStorage;
		this.world = worldStorage.getWorld();
		String dimFolder = this.world.provider.getSaveFolder();
		this.localStorageDir = new File(this.world.getSaveHandler().getWorldDirectory(), (dimFolder != null && dimFolder.length() > 0 ? dimFolder + File.separator : "") + "data" + File.separator + "local_storage" + File.separator);
		this.regionCache = new LocalRegionCache(this, new File(this.localStorageDir, "region"));
	}

	@Override
	public IWorldStorage getWorldStorage() {
		return this.worldStorage;
	}

	@Override
	public boolean addLocalStorage(ILocalStorage storage) {
		return this.addLocalStorageInternal(storage, true);
	}

	protected boolean addLocalStorageInternal(ILocalStorage storage, boolean isInitialAdd) {
		if(!this.localStorage.containsKey(storage.getID())) {
			this.localStorage.put(storage.getID(), storage);

			if(storage instanceof ITickable) {
				this.tickableLocalStorage.add(storage);
			}

			if(isInitialAdd) {
				storage.onAdded();
			}

			storage.onLoaded();

			boolean isReferenced = false;

			//Add already loaded references
			for(ChunkPos referenceChunk : storage.getLinkedChunks()) {
				Chunk chunk = this.world.getChunkProvider().getLoadedChunk(referenceChunk.x, referenceChunk.z);
				if(chunk != null) {
					IChunkStorage chunkStorage = this.worldStorage.getChunkStorage(chunk);
					if(chunkStorage != null) {
						LocalStorageReference reference = chunkStorage.getReference(storage.getID());
						if(reference != null) {
							isReferenced = true;

							if(!storage.getLoadedReferences().contains(reference)) {
								//Add reference
								storage.loadReference(reference);
							}
						}
					}
				}
			}

			if(!isReferenced && isInitialAdd && !this.world.isRemote) {
				//Queue storage to be checked in the next tick.
				//If it is still unreferenced it will be unloaded.
				this.pendingUnreferencedStorages.add(storage);
			}

			return true;
		}
		return false;
	}

	@Override
	public boolean removeLocalStorage(ILocalStorage storage) {
		if(this.localStorage.containsKey(storage.getID())) {
			storage.onRemoving();

			if(!this.world.isRemote) {
				storage.unlinkAllChunks();
			}

			this.localStorage.remove(storage.getID());

			Iterator<ILocalStorage> tickableIt = this.tickableLocalStorage.iterator();
			while(tickableIt.hasNext()) {
				ILocalStorage tickableStorage = tickableIt.next();
				if(storage.getID().equals(tickableStorage.getID())) {
					tickableIt.remove();
				}
			}

			Iterator<ILocalStorage> pendingIt = this.pendingUnreferencedStorages.iterator();
			while(pendingIt.hasNext()) {
				ILocalStorage pendingStorage = pendingIt.next();
				if(storage.getID().equals(pendingStorage.getID())) {
					pendingIt.remove();
				}
			}

			boolean wasSavedToRegion = false;

			if(!this.world.isRemote) {
				wasSavedToRegion = this.deleteLocalStorageFileInternal(storage);
			}

			storage.onUnloaded();

			storage.onRemoved();

			//A region only has a reference from a storage if that storage was new and saved to that
			//region or if it was loaded from that region. Only in those cases the region reference
			//counter needs to be decremented and the region unloaded if no longer referenced.
			if(wasSavedToRegion && !this.world.isRemote) {
				LocalRegion region = storage.getRegion();

				if(region != null) {
					this.decrRegionRef(this.regionCache.getCachedRegion(region), null, true);
				}
			}

			return true;
		}
		return false;
	}

	@Override
	public ILocalStorage getLocalStorage(StorageID id) {
		return this.localStorage.get(id);
	}

	@SuppressWarnings("unchecked")
	@Override
	public <T extends ILocalStorage> List<T> getLocalStorages(Class<T> type, double x, double z, @Nullable Predicate<T> filter) {
		List<T> storages = new ArrayList<>();
		int cx = MathHelper.floor(x) >> 4;
		int cz = MathHelper.floor(z) >> 4;
		Chunk chunk = this.world.getChunk(cx, cz);
		IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(chunk);
		if(chunkStorage != null) {
			for(LocalStorageReference ref : chunkStorage.getLocalStorageReferences()) {
				ILocalStorage localStorage = this.getLocalStorage(ref.getID());
				if(localStorage != null && localStorage.getBoundingBox() != null && type.isAssignableFrom(localStorage.getClass())
						&& (filter == null || filter.apply((T) localStorage))) {
					if(!storages.contains(localStorage)) {
						storages.add((T) localStorage);
					}
				}
			}
		}
		return storages;
	}

	@SuppressWarnings("unchecked")
	@Override
	public <T extends ILocalStorage> List<T> getLocalStorages(Class<T> type, AxisAlignedBB aabb, @Nullable Predicate<T> filter) {
		List<T> storages = new ArrayList<>();
		int sx = MathHelper.floor(aabb.minX) >> 4;
		int sz = MathHelper.floor(aabb.minZ) >> 4;
		int ex = MathHelper.floor(aabb.maxX) >> 4;
		int ez = MathHelper.floor(aabb.maxZ) >> 4;
		for(int cx = sx; cx <= ex; cx++) {
			for(int cz = sz; cz <= ez; cz++) {
				Chunk chunk = this.world.getChunk(cx, cz);
				IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(chunk);
				if(chunkStorage != null) {
					for(LocalStorageReference ref : chunkStorage.getLocalStorageReferences()) {
						ILocalStorage localStorage = this.getLocalStorage(ref.getID());
						if(localStorage != null && localStorage.getBoundingBox() != null && type.isAssignableFrom(localStorage.getClass()) && localStorage.getBoundingBox().intersects(aabb)
								&& (filter == null || filter.apply((T) localStorage))) {
							if(!storages.contains(localStorage)) {
								storages.add((T) localStorage);
							}
						}
					}
				}
			}
		}
		return storages;
	}

	@Override
	public void deleteLocalStorageFile(ILocalStorage storage) {
		this.deleteLocalStorageFileInternal(storage);
	}

	private boolean deleteLocalStorageFileInternal(ILocalStorage storage) {
		if(storage.getRegion() == null) {
			File file = new File(this.getLocalStorageDirectory(), storage.getID().getStringID() + ".dat");
			this.saveHandler.queueLocalStorage(file, null);
		} else {
			LocalRegionData data = this.regionCache.getOrCreateRegion(storage.getRegion(), false);

			if(data != null) {
				this.incrRegionRef(data);

				try {
					return data.deleteLocalStorage(this.regionCache.getDir(), storage.getID());
				} finally {
					this.decrRegionRef(data, null, true);
				}
			}
		}

		return false;
	}

	@Override
	public void saveLocalStorageFile(ILocalStorage storage) {
		this.saveLocalStorageFile(storage, false);
	}

	private void saveLocalStorageFile(ILocalStorage storage, boolean skipRegionUnloading) {
		NBTTagCompound nbt = this.saveLocalStorageToNBT(new NBTTagCompound(), storage);
		if(storage.getRegion() == null) {
			File file = new File(this.getLocalStorageDirectory(), storage.getID().getStringID() + ".dat");
			this.saveHandler.queueLocalStorage(file, nbt);
		} else {
			LocalRegion region = storage.getRegion();
			LocalRegionData data = this.regionCache.getOrCreateRegion(region);

			boolean isLoaded = !storage.getLoadedReferences().isEmpty() && this.getLocalStorage(storage.getID()) != null;
			boolean isFromRegion = data.getLocalStorageNBT(storage.getID()) != null;
			boolean isNewStorage = isLoaded && !isFromRegion;

			this.incrRegionRef(data);

			try {
				data.setLocalStorageNBT(storage.getID(), nbt);
			} finally {
				if(skipRegionUnloading) {
					this.decrRegionRef(data, null, false);
				} else {
					//If the region is new, i.e. was properly added but not loaded from a region, then
					//the region need not be unloaded or the region reference counter need not be decreased,
					//because we can be sure that this will happen later on.
					//In all other cases this should normally not cause the region to be unloaded unless the local storage
					//is a dangling instance or the region was not loaded properly, because when loaded properly the region
					//should also be loaded and be referenced accordingly. The only safe way to proceed if the region was
					//not loaded or not referenced properly is to immediately unload the region again to prevent a dangling region.
					if(!isNewStorage && this.decrRegionRef(data, null, true)) {
						TheBetweenlands.logger.warn(String.format("Saving local storage with ID %s, but its region %s was not loaded. This should not happen...", storage.getID().getStringID(), data.getID()));
					}
				}
			}
		}
	}

	@Nullable
	private ILocalStorage loadLocalStorageUnsafe(LocalStorageReference reference) {
		if(!this.world.isRemote) {
			try {
				ILocalStorage storage = this.createLocalStorageFromFile(reference);
				if(storage != null) {
					this.addLocalStorageInternal(storage, false);

					LocalRegion region = storage.getRegion();
					if(region != null) {
						LocalRegionData data = this.regionCache.getOrCreateRegion(region);
						this.incrRegionRef(data);
					}
				}
				return storage;
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed loading local storage with ID %s at %s", reference.getID().getStringID(), "[x=" + reference.getChunk().x + ", z=" + reference.getChunk().z + "]"), ex);
			}
		}
		return null;
	}

	@Deprecated
	@Override
	public ILocalStorage loadLocalStorage(LocalStorageReference reference) {
		return this.loadLocalStorageUnsafe(reference);
	}

	@Override
	public ILocalStorageHandle getOrLoadLocalStorage(LocalStorageReference reference) {
		ILocalStorage storage = this.getLocalStorage(reference.getID());

		//If not already loaded try to load from file
		if(storage == null && !this.world.isRemote) {
			storage = this.loadLocalStorageUnsafe(reference);
		}

		if(storage != null) {
			return new LocalStorageHandleImpl(storage, reference);
		}

		return null;
	}

	/**
	 * Creates an instance of the local storage specified by the reference
	 * @param reference
	 * @return
	 */
	@Nullable
	private ILocalStorage createLocalStorageFromFile(LocalStorageReference reference) {
		if(!reference.hasRegion()) {
			File file = new File(this.getLocalStorageDirectory(), reference.getID().getStringID() + ".dat");
			try {
				NBTTagCompound nbt = this.saveHandler.loadFileNbt(file);;
				if(nbt != null) {
					return this.createLocalStorageFromNBT(nbt, null);
				}
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed reading local storage %s from file: %s", reference.getID().getStringID(), file.getAbsolutePath()), ex);
			}
		} else {
			LocalRegionData region = this.regionCache.getOrCreateRegion(reference.getRegion());
			NBTTagCompound nbt = region.getLocalStorageNBT(reference.getID());
			if(nbt != null) {
				return this.createLocalStorageFromNBT(nbt, reference.getRegion());
			}
		}
		return null;
	}

	private void incrRegionRef(@Nullable LocalRegionData data) {
		if(data != null) {
			data.incrRefCounter();

			if(data.hasReferences()) {
				this.pendingUnreferencedRegions.remove(data);
			}
		}
	}

	private boolean decrRegionRef(@Nullable LocalRegionData data, @Nullable StorageID checkID, boolean saveAndUnload) {
		if(data != null && (checkID == null || data.getLocalStorageNBT(checkID) != null)) {
			data.decrRefCounter();

			if(!data.hasReferences()) {
				if(saveAndUnload) {
					this.pendingUnreferencedRegions.put(data, this.world.getTotalWorldTime());
				}

				return true;
			}
		}

		return false;
	}

	@Override
	public boolean unloadLocalStorage(ILocalStorage storage) {
		if(this.localStorage.containsKey(storage.getID())) {
			//Only save if dirty
			if(!this.world.isRemote && storage.isDirty()) {
				//Skip region unloading because that'll be handled after
				//unloading the local storage
				this.saveLocalStorageFile(storage, true);
				storage.setDirty(false);
			}

			this.localStorage.remove(storage.getID());

			Iterator<ILocalStorage> tickableIt = this.tickableLocalStorage.iterator();
			while(tickableIt.hasNext()) {
				ILocalStorage tickableStorage = tickableIt.next();
				if(storage.getID().equals(tickableStorage.getID())) {
					tickableIt.remove();
				}
			}

			Iterator<ILocalStorage> pendingIt = this.pendingUnreferencedStorages.iterator();
			while(pendingIt.hasNext()) {
				ILocalStorage pendingStorage = pendingIt.next();
				if(storage.getID().equals(pendingStorage.getID())) {
					pendingIt.remove();
				}
			}

			storage.onUnloaded();

			if(!this.world.isRemote) {
				LocalRegion region = storage.getRegion();

				if(region != null) {
					//A region only has a reference from a storage if that storage was new and saved to that
					//region or if it was loaded from that region. Only in those cases the region reference
					//counter needs to be decremented and the region unloaded if no longer referenced, hence
					//decrRegionRef needs to check if the region data contains that storage.
					this.decrRegionRef(this.regionCache.getCachedRegion(region), storage.getID(), true);
				}
			}

			return true;
		}
		return false;
	}

	@Override
	public Collection<ILocalStorage> getLoadedStorages() {
		return Collections.unmodifiableCollection(this.localStorage.values());
	}

	@Override
	public File getLocalStorageDirectory() {
		return this.localStorageDir;
	}

	@Override
	public void update() {
		for(int i = 0; i < this.tickableLocalStorage.size(); i++) {
			ILocalStorage localStorage = this.tickableLocalStorage.get(i);
			((ITickable)localStorage).update();

			IGenericDataManagerAccess dataManager = localStorage.getDataManager();
			if(dataManager != null) {
				dataManager.update();
				if(dataManager.isDirty()) {
					MessageSyncLocalStorageData message = new MessageSyncLocalStorageData(localStorage, false);
					for (EntityPlayerMP watcher : localStorage.getWatchers()) {
						TheBetweenlands.networkWrapper.sendTo(message, watcher);
					}
				}
			}
		}

		if(!this.world.isRemote) {
			for(int i = 0; i < this.pendingUnreferencedStorages.size(); i++) {
				ILocalStorage localStorage = this.pendingUnreferencedStorages.get(i);

				if(localStorage.getLoadedReferences().isEmpty() && this.getLocalStorage(localStorage.getID()) != null) {
					//Storage is not referenced by any chunk and being added for the first time.
					//Linking probably deferred. Save and unload storage until needed.
					this.unloadLocalStorage(localStorage);
				}
			}

			TObjectLongIterator<LocalRegionData> pendingUnreferencedRegionsIT = this.pendingUnreferencedRegions.iterator();
			while(pendingUnreferencedRegionsIT.hasNext()) {
				pendingUnreferencedRegionsIT.advance();

				if(this.world.getTotalWorldTime() - pendingUnreferencedRegionsIT.value() > 20) {
					LocalRegionData data = pendingUnreferencedRegionsIT.key();

					pendingUnreferencedRegionsIT.remove();

					if(data.isDirty()) {
						data.saveRegion(this.regionCache.getDir());
					}

					this.regionCache.removeRegion(data.getRegion());
				}
			}
		}
		this.pendingUnreferencedStorages.clear();
	}

	@Override
	public ILocalStorage createLocalStorageFromNBT(NBTTagCompound nbt, @Nullable LocalRegion region) {
		ResourceLocation type = new ResourceLocation(nbt.getString("type"));
		StorageID id = StorageID.readFromNBT(nbt);
		ILocalStorage storage = this.createLocalStorage(type, id, region);
		storage.readFromNBT(nbt.getCompoundTag("data"));
		return storage;
	}

	@Override
	public ILocalStorage createLocalStorage(ResourceLocation type, StorageID id, @Nullable LocalRegion region) {
		StorageRegistry.Factory<? extends ILocalStorage> factory = StorageRegistry.getStorageFactory(type);
		if (factory == null) {
			throw new RuntimeException("Local storage type not mapped: " + type);
		}
		return factory.create(this.worldStorage, id, region);
	}

	@Override
	public NBTTagCompound saveLocalStorageToNBT(NBTTagCompound nbt, ILocalStorage storage) {
		ResourceLocation type = StorageRegistry.getStorageId(storage.getClass());
		if (type == null) {
			throw new RuntimeException("Local storage type not mapped: " + storage);
		}
		nbt.setString("type", type.toString());
		storage.getID().writeToNBT(nbt);
		nbt.setTag("data", storage.writeToNBT(new NBTTagCompound()));
		return nbt;
	}

	@Override
	public void queueDeferredOperation(ChunkPos chunk, IDeferredStorageOperation operation) {
		//Run immediately if chunk is already loaded
		Chunk loadedChunk = this.getWorldStorage().getWorld().getChunkProvider().getLoadedChunk(chunk.x, chunk.z);
		if(loadedChunk != null) {
			IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(loadedChunk);
			operation.apply(chunkStorage);
			return;
		}

		LocalRegion region = LocalRegion.getFromBlockPos(chunk.x * 16, chunk.z * 16);
		LocalRegionData data = this.regionCache.getOrCreateRegion(region);

		this.incrRegionRef(data);

		try {
			NBTTagCompound chunkNbt = data.getChunkNBT(chunk);
			if(chunkNbt == null) {
				chunkNbt = new NBTTagCompound();
			}

			NBTTagList operationsNbt = chunkNbt.getTagList("DeferredOperations", Constants.NBT.TAG_COMPOUND);

			ResourceLocation type = StorageRegistry.getDeferredOperationId(operation.getClass());
			if (type == null) {
				throw new RuntimeException("Deferred storage operation type not mapped: " + operation);
			}

			NBTTagCompound nbt = new NBTTagCompound();
			nbt.setString("type", type.toString());
			nbt.setTag("data", operation.writeToNBT(new NBTTagCompound()));

			operationsNbt.appendTag(nbt);
			chunkNbt.setTag("DeferredOperations", operationsNbt);

			data.setChunkNBT(chunk, chunkNbt);
		} finally {
			this.decrRegionRef(data, null, true);
		}
	}

	@Override
	public void loadDeferredOperations(IChunkStorage storage) {
		ChunkPos chunk = storage.getChunk().getPos();

		LocalRegion region = LocalRegion.getFromBlockPos(chunk.x * 16, chunk.z * 16);
		LocalRegionData data = this.regionCache.getOrCreateRegion(region, false);

		if(data != null) {
			this.incrRegionRef(data);

			try {
				NBTTagCompound chunkNbt = data.getChunkNBT(chunk);

				if(chunkNbt != null && chunkNbt.hasKey("DeferredOperations", Constants.NBT.TAG_LIST)) {
					NBTTagList operationsNbt = chunkNbt.getTagList("DeferredOperations", Constants.NBT.TAG_COMPOUND);

					for(int i = 0; i < operationsNbt.tagCount(); i++) {
						NBTTagCompound nbt = operationsNbt.getCompoundTagAt(i);

						ResourceLocation type = new ResourceLocation(nbt.getString("type"));

						Supplier<? extends IDeferredStorageOperation> factory = StorageRegistry.getDeferredOperationFactory(type);
						if (factory == null) {
							TheBetweenlands.logger.error("Deferred storage operation type not mapped: " + type + ". Skipping...");
							continue;
						}

						IDeferredStorageOperation operation = factory.get();

						operation.readFromNBT(nbt.getCompoundTag("data"));

						operation.apply(storage);
					}

					//Clear deferred operations
					chunkNbt.removeTag("DeferredOperations");

					data.setChunkNBT(chunk, chunkNbt);
				}
			} finally {
				this.decrRegionRef(data, null, true);
			}
		}
	}

	public LocalStorageSaveHandler getSaveHandler() {
		return this.saveHandler;
	}

	@Override
	public void saveAll() {
		//Save loaded storages
		for(ILocalStorage localStorage : this.getLoadedStorages()) {
			//Only save if dirty
			if(localStorage.isDirty()) {
				this.saveLocalStorageFile(localStorage);
				localStorage.setDirty(false);
			}
		}

		//Save and unload all unreferenced regions
		for(LocalRegionData data : this.pendingUnreferencedRegions.keySet()) {
			if(data.isDirty()) {
				data.saveRegion(this.regionCache.getDir());
			}

			this.regionCache.removeRegion(data.getRegion());
		}
		this.pendingUnreferencedRegions.clear();

		//Save rest of regional cache
		this.regionCache.saveAllRegions();
	}
}

package thebetweenlands.common.world.storage;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import javax.annotation.Nullable;

import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityDispatcher;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.fml.common.network.simpleimpl.IMessage;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.event.AttachLocalStorageCapabilitiesEvent;
import thebetweenlands.api.storage.IChunkStorage;
import thebetweenlands.api.storage.ILocalStorage;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.LocalStorageReference;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.network.clientbound.MessageAddLocalStorage;
import thebetweenlands.common.network.clientbound.MessageRemoveLocalStorage;
import thebetweenlands.common.world.storage.operation.DeferredLinkOperation;

public abstract class LocalStorageImpl implements ILocalStorage {
	private final IWorldStorage worldStorage;
	private final LocalRegion region;
	private final StorageID id;

	private CapabilityDispatcher capabilities;
	private boolean dirty;

	private final List<ChunkPos> linkedChunks = new ArrayList<>();
	private final List<LocalStorageReference> loadedReferences = new ArrayList<>();

	//protected boolean requiresSync = false;

	private final List<EntityPlayerMP> watchers = new ArrayList<>();
	private final List<EntityPlayerMP> duplicateWatchers = new ArrayList<>();

	private boolean loaded = false;

	public LocalStorageImpl(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region) {
		this.worldStorage = worldStorage;
		this.id = id;
		this.region = region;

		//Gather capabilities
		AttachLocalStorageCapabilitiesEvent event = new AttachLocalStorageCapabilitiesEvent(this);
		MinecraftForge.EVENT_BUS.post(event);
		this.capabilities = event.getCapabilities().size() > 0 ? new CapabilityDispatcher(event.getCapabilities(), null) : null;
	}

	@Override
	public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
		return this.capabilities == null ? false : this.capabilities.hasCapability(capability, facing);
	}

	@Override
	public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
		return this.capabilities == null ? null : this.capabilities.getCapability(capability, facing);
	}

	@Override
	public IWorldStorage getWorldStorage() {
		return this.worldStorage;
	}

	@Override
	public StorageID getID() {
		return this.id;
	}

	@Override
	public LocalRegion getRegion() {
		return this.region;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		if(this.capabilities != null && nbt.hasKey("ForgeCaps")) {
			this.capabilities.deserializeNBT(nbt.getCompoundTag("ForgeCaps"));
		}

		this.readReferenceChunks(nbt);
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		if(this.capabilities != null) {
			NBTTagCompound caps = this.capabilities.serializeNBT();
			if(caps.getSize() > 0) {
				nbt.setTag("ForgeCaps", caps);
			}
		}

		this.writeReferenceChunks(nbt);

		return nbt;
	}

	@Override
	public void readInitialPacket(NBTTagCompound nbt) {
		this.readReferenceChunks(nbt);
	}

	@Override
	public NBTTagCompound writeInitialPacket(NBTTagCompound nbt) {
		this.writeReferenceChunks(nbt);
		return nbt;
	}

	protected final void writeReferenceChunks(NBTTagCompound nbt) {
		NBTTagList referenceChunkList = new NBTTagList();
		for(ChunkPos referenceChunk : this.linkedChunks) {
			NBTTagCompound referenceChunkNbt = new NBTTagCompound();
			referenceChunkNbt.setInteger("x", referenceChunk.x);
			referenceChunkNbt.setInteger("z", referenceChunk.z);
			referenceChunkList.appendTag(referenceChunkNbt);
		}
		nbt.setTag("ReferenceChunks", referenceChunkList);
	}

	protected final void readReferenceChunks(NBTTagCompound nbt) {
		this.linkedChunks.clear();
		NBTTagList referenceChunkList = nbt.getTagList("ReferenceChunks", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < referenceChunkList.tagCount(); i++) {
			NBTTagCompound referenceChunkNbt = referenceChunkList.getCompoundTagAt(i);
			this.linkedChunks.add(new ChunkPos(referenceChunkNbt.getInteger("x"), referenceChunkNbt.getInteger("z")));
		}
	}

	@Override
	public void markDirty() {
		this.setDirty(true);
	}

	/**
	 * Sets whether the data is dirty and needs to be saved to the file
	 * @param dirty
	 * @return
	 */
	@Override
	public void setDirty(boolean dirty) {
		this.dirty = dirty;
	}

	@Override
	public boolean isDirty() {
		return this.dirty;
	}

	@Override
	public List<ChunkPos> getLinkedChunks() {
		return Collections.unmodifiableList(this.linkedChunks);
	}

	@Override
	@SideOnly(Side.CLIENT)
	public void setLinkedChunks(List<ChunkPos> linkedChunks) {
		this.linkedChunks.clear();
		this.linkedChunks.addAll(linkedChunks);
	}

	@Override
	public void onLoaded() {
		this.loaded = true;
	}

	@Override
	public void onUnloaded() {
		this.loaded = false;
	}

	@Override
	public void onRemoved() {

	}

	@Override
	public void onRemoving() {
		//Notify clients when shared storage is removed.
		//This is done before onRemoved so that the list of watchers is not yet empty.
		if(!this.getWorldStorage().getWorld().isRemote) {
			if (!this.getWatchers().isEmpty()) {
				this.sendMessageToAllWatchers(new MessageRemoveLocalStorage(this.getID()));
			}
		}
	}

	@Override
	public Collection<LocalStorageReference> getLoadedReferences() {
		return Collections.unmodifiableCollection(this.loadedReferences);
	}

	@Override
	public boolean loadReference(LocalStorageReference reference) {
		if(!this.loadedReferences.contains(reference)) {
			return this.loadedReferences.add(reference);
		}
		return false;
	}

	@Override
	public boolean unloadReference(LocalStorageReference reference) {
		return this.loadedReferences.remove(reference);
	}

	@Override
	public boolean addWatcher(IChunkStorage chunkStorage, EntityPlayerMP player) {
		boolean contained = this.duplicateWatchers.contains(player);
		this.duplicateWatchers.add(player);
		if(!contained) {
			this.watchers.add(player);
			this.onWatched(player);
		}
		return !contained;
	}

	/**
	 * Called when a new watcher is added
	 * @param player
	 */
	protected void onWatched(EntityPlayerMP player) {
		this.sendDataToPlayer(new MessageAddLocalStorage(this), player);
	}

	@Override
	public boolean removeWatcher(IChunkStorage chunkStorage, EntityPlayerMP player) {
		boolean contained = this.duplicateWatchers.remove(player);
		if(contained && !this.duplicateWatchers.contains(player)) {
			this.watchers.remove(player);
			this.onUnwatched(player);
		}
		return contained;
	}

	/**
	 * Called when a player stops watching this local storage
	 * @param player
	 */
	protected void onUnwatched(EntityPlayerMP player) {

	}

	@Override
	public Collection<EntityPlayerMP> getWatchers() {
		return Collections.unmodifiableCollection(this.watchers);
	}

	@Override
	public boolean unlinkAllChunks() {
		boolean changed = false;
		boolean allUnlinked = true;
		List<ChunkPos> chunks = new ArrayList<>(this.linkedChunks.size());
		chunks.addAll(this.linkedChunks);
		Iterator<ChunkPos> it = chunks.iterator();
		ChunkPos pos = null;
		while(it.hasNext()) {
			pos = it.next();
			Chunk chunk = this.worldStorage.getWorld().getChunk(pos.x, pos.z);
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData == null || !chunkData.unlinkLocalStorage(this)) {
				allUnlinked = false;
			} else if(chunkData != null) {
				changed = true;
			}
		}
		if(changed) {
			this.setDirty(true);
		}
		this.linkedChunks.clear();
		return allUnlinked;
	}

	@Override
	public boolean linkChunk(Chunk chunk) {
		ChunkPos chunkPos = new ChunkPos(chunk.x, chunk.z);
		if(!this.linkedChunks.contains(chunkPos)) {
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData != null && chunkData.linkLocalStorage(this)) {
				if(this.linkedChunks.add(chunkPos)) {
					//TODO Send packet
					this.setDirty(true);
					return true;
				}
			}
		}
		return false;
	}

	@Override
	public void linkChunkDeferred(ChunkPos chunk) {
		if(!this.linkedChunks.contains(chunk) && this.linkedChunks.add(chunk)) {
			this.setDirty(true);
			this.worldStorage.getLocalStorageHandler().queueDeferredOperation(chunk, new DeferredLinkOperation(new LocalStorageReference(chunk, this.getID(), this.getRegion())));
		}
	}

	@Override
	public boolean unlinkChunk(Chunk chunk) {
		ChunkPos chunkPos = new ChunkPos(chunk.x, chunk.z);
		if(this.linkedChunks.contains(chunkPos)) {
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData != null) {
				chunkData.unlinkLocalStorage(this);
				if(this.linkedChunks.remove(chunkPos)) {
					//TODO Send packet
					this.setDirty(true);
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Sends the message to all watching players
	 */
	protected void sendMessageToAllWatchers(IMessage message) {
		for (EntityPlayerMP watcher : this.getWatchers()) {
			this.sendDataToPlayer(message, watcher);
		}
	}

	/**
	 * Sends the message to a player
	 * @param player
	 */
	protected void sendDataToPlayer(IMessage message, EntityPlayerMP player) {
		TheBetweenlands.networkWrapper.sendTo(message, player);
	}

	@Override
	public boolean isLoaded() {
		return this.loaded;
	}
}

package thebetweenlands.common.world.storage;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import javax.annotation.Nullable;

import gnu.trove.map.TObjectIntMap;
import gnu.trove.map.hash.TObjectIntHashMap;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.ChunkPos;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.loot.ISharedLootPool;
import thebetweenlands.api.network.IGenericDataManagerAccess;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.loot.shared.SharedLootPool;

public class SharedLootPoolStorage extends LocalStorageImpl {
	private Map<ResourceLocation, SharedLootPool> sharedLootPools = new HashMap<>();
	private TObjectIntMap<ResourceLocation> lootInventories = new TObjectIntHashMap<>();

	private long lootSeed;

	public SharedLootPoolStorage(IWorldStorage worldStorage, StorageID id, LocalRegion region) {
		super(worldStorage, id, region);
	}

	public SharedLootPoolStorage(IWorldStorage worldStorage, StorageID id, LocalRegion region, long lootSeed) {
		super(worldStorage, id, region);
		this.lootSeed = lootSeed;
	}

	@Override
	public AxisAlignedBB getBoundingBox() {
		//No bounding box required.
		//Loot inventories are directly linked to the storage by storage ID.
		return null;
	}

	@Override
	public IGenericDataManagerAccess getDataManager() {
		return null;
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt = super.writeToNBT(nbt);

		if(!this.sharedLootPools.isEmpty()) {
			NBTTagList sharedLootPoolsNbt = new NBTTagList();

			for(SharedLootPool sharedLootPool : this.sharedLootPools.values()) {
				sharedLootPoolsNbt.appendTag(sharedLootPool.writeToNBT(new NBTTagCompound()));
			}

			nbt.setTag("sharedLootPools", sharedLootPoolsNbt);
		}

		if(!this.lootInventories.isEmpty()) {
			NBTTagList lootInventoriesNbt = new NBTTagList();
			this.lootInventories.forEachEntry((table, count) -> {
				NBTTagCompound entryNbt = new NBTTagCompound();
				entryNbt.setString("table", table.toString());
				entryNbt.setInteger("count", count);
				lootInventoriesNbt.appendTag(entryNbt);
				return true;
			});
			nbt.setTag("lootInventories", lootInventoriesNbt);
		}

		return nbt;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);

		this.sharedLootPools.clear();
		NBTTagList sharedLootPoolsNbt = nbt.getTagList("sharedLootPools", Constants.NBT.TAG_COMPOUND);

		for(int i = 0; i < sharedLootPoolsNbt.tagCount(); i++) {
			SharedLootPool sharedLootPool = new SharedLootPool(sharedLootPoolsNbt.getCompoundTagAt(i), this);
			ResourceLocation lootTable = sharedLootPool.getLootTable();
			if(lootTable != null) {
				this.sharedLootPools.put(lootTable, sharedLootPool);
			}
		}

		this.lootInventories.clear();
		NBTTagList lootInventoriesNbt = nbt.getTagList("lootInventories", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < lootInventoriesNbt.tagCount(); i++) {
			NBTTagCompound entryNbt = lootInventoriesNbt.getCompoundTagAt(i);
			this.lootInventories.put(new ResourceLocation(entryNbt.getString("table")), entryNbt.getInteger("count"));
		}
	}

	public int getSharedLootInventories(ResourceLocation lootTable) {
		return this.lootInventories.get(lootTable);
	}

	public void registerSharedLootInventory(BlockPos pos, ResourceLocation lootTable) {
		this.lootInventories.adjustOrPutValue(lootTable, 1, 1);

		//Make sure this storage is linked to the chunk the loot inventory is in
		this.linkChunkSafely(new ChunkPos(pos));

		this.markDirty();
	}

	@Nullable
	public ISharedLootPool getSharedLootPool(ResourceLocation lootTable) {
		return this.sharedLootPools.get(lootTable);
	}

	@Nullable
	public ISharedLootPool getOrCreateSharedLootPool(ResourceLocation lootTable) {
		ISharedLootPool pool = this.getSharedLootPool(lootTable);

		if(pool != null) {
			return pool;
		}

		SharedLootPool newPool = new SharedLootPool(lootTable, this.lootSeed, this);
		this.sharedLootPools.put(lootTable, newPool);
		this.markDirty();

		return newPool;
	}

	@Nullable
	public ISharedLootPool removeSharedLootPool(ResourceLocation lootTable) {
		ISharedLootPool pool = this.sharedLootPools.remove(lootTable);
		if(pool != null) {
			this.markDirty();
		}

		return pool;
	}

	public Set<ResourceLocation> getSharedLootPoolKeys() {
		return this.sharedLootPools.keySet();
	}
}

package thebetweenlands.common.world.storage.location;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ITickable;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos.PooledMutableBlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.config.BetweenlandsConfig;

public class LocationTokenBucket extends LocationStorage implements ITickable {

	private static class Ticket {
		private final ResourceLocation key;
		private final AxisAlignedBB area;

		private int counter;

		private float reservedTokenFraction;
		private long reservedTokens;

		private boolean loaded = true;

		private Ticket(ResourceLocation key, AxisAlignedBB area) {
			this.key = key;
			this.area = area;
		}
	}

	private ResourceLocation bucketId;

	private boolean useWorldtime = true;
	private int expirationTime = 1200;
	private int minTokensPerTick = 1, maxTokensPerTick = 1;
	private double limitMultiplier = 0.99D;

	private final List<Ticket> tickets = new ArrayList<>();
	private final Map<ResourceLocation, Ticket> key2tickets = new HashMap<>();

	private long lastCheckedTime;

	private float sharedTokenFraction;
	private long sharedTokens;

	public LocationTokenBucket(IWorldStorage worldStorage, StorageID id, LocalRegion region) {
		super(worldStorage, id, region, "token_bucket", EnumLocationType.NONE);
	}

	public LocationTokenBucket(IWorldStorage worldStorage, StorageID id, LocalRegion region, AxisAlignedBB aabb, ResourceLocation bucketId) {
		this(worldStorage, id, region);
		this.addBounds(aabb);
		this.bucketId = bucketId;
		this.lastCheckedTime = worldStorage.getWorld().getTotalWorldTime();
	}

	public ResourceLocation getBucketId() {
		return this.bucketId;
	}

	public LocationTokenBucket setUseWorldTime(boolean useWorldTime) {
		this.useWorldtime = useWorldTime;
		this.markDirty();
		return this;
	}

	public LocationTokenBucket setExpirationTime(int time) {
		this.expirationTime = time;
		this.markDirty();
		return this;
	}

	public void refreshTicket(ResourceLocation key, AxisAlignedBB area) {
		if(area.intersects(this.getBoundingBox())) {
			Ticket ticket = this.key2tickets.get(key);
			if(ticket == null) {
				ticket = new Ticket(key, area);
				this.tickets.add(ticket);
				this.key2tickets.put(key, ticket);
			}
			ticket.counter = 0;
			this.sharedTokens += ticket.reservedTokens;
			ticket.reservedTokens = 0;
			this.markDirty();
		}
	}

	public LocationTokenBucket setMinTokensPerTick(int min) {
		this.minTokensPerTick = MathHelper.clamp(min, 0, this.maxTokensPerTick);
		this.markDirty();
		return this;
	}

	public LocationTokenBucket setMaxTokensPerTick(int max) {
		this.maxTokensPerTick = Math.max(this.minTokensPerTick, max);
		this.markDirty();
		return this;
	}

	public LocationTokenBucket setTokensPerTick(int min, int max) {
		this.minTokensPerTick = Math.max(0, min);
		this.setMaxTokensPerTick(max);
		this.markDirty();
		return this;
	}

	public LocationTokenBucket setLimitMultiplier(double multiplier) {
		this.limitMultiplier = multiplier;
		return this;
	}

	public long getTokens() {
		return this.sharedTokens;
	}

	public long consumeTokens(long tokens) {
		long consumed = Math.max(0, Math.min(tokens, this.sharedTokens));
		this.sharedTokens -= consumed;
		this.markDirty();
		return consumed;
	}

	public boolean consumeTokensAtomically(long tokens) {
		if(this.sharedTokens >= tokens) {
			this.sharedTokens -= tokens;
			this.markDirty();
			return true;
		}
		return false;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);

		this.bucketId = new ResourceLocation(nbt.getString("bucketId"));
		this.useWorldtime = nbt.getBoolean("fillWhenUnloaded");
		this.expirationTime = nbt.getInteger("expirationTime");
		this.minTokensPerTick = nbt.getInteger("minTokensPerTick");
		this.maxTokensPerTick = nbt.getInteger("maxTokensPerTick");

		this.lastCheckedTime = nbt.getLong("lastCheckedTime");
		this.sharedTokens = nbt.getLong("tokens");

		this.tickets.clear();
		this.key2tickets.clear();
		NBTTagList ticketsNbt = nbt.getTagList("tickets", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < ticketsNbt.tagCount(); i++) {
			NBTTagCompound ticketNbt = ticketsNbt.getCompoundTagAt(i);
			ResourceLocation key = new ResourceLocation(ticketNbt.getString("key"));
			Ticket ticket = new Ticket(key, new AxisAlignedBB(
					ticketNbt.getDouble("minX"), ticketNbt.getDouble("minY"), ticketNbt.getDouble("minZ"),
					ticketNbt.getDouble("maxX"), ticketNbt.getDouble("maxY"), ticketNbt.getDouble("maxZ")
					));
			ticket.counter = ticketNbt.getInteger("counter");
			ticket.reservedTokens = ticketNbt.getLong("reservedTokens");
			this.tickets.add(ticket);
			this.key2tickets.put(key, ticket);
		}
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt = super.writeToNBT(nbt);

		nbt.setString("bucketId", this.bucketId.toString());
		nbt.setBoolean("fillWhenUnloaded", this.useWorldtime);
		nbt.setInteger("expirationTime", this.expirationTime);
		nbt.setInteger("minTokensPerTick", this.minTokensPerTick);
		nbt.setInteger("maxTokensPerTick", this.maxTokensPerTick);

		nbt.setLong("lastCheckedTime", this.lastCheckedTime);
		nbt.setLong("tokens", this.sharedTokens);

		NBTTagList ticketsNbt = new NBTTagList();
		for(Ticket ticket : this.tickets) {
			NBTTagCompound ticketNbt = new NBTTagCompound();
			ticketNbt.setInteger("counter", ticket.counter);
			ticketNbt.setLong("reservedTokens", ticket.reservedTokens);
			ticketNbt.setString("key", ticket.key.toString());
			ticketNbt.setDouble("minX", ticket.area.minX);
			ticketNbt.setDouble("minY", ticket.area.minY);
			ticketNbt.setDouble("minZ", ticket.area.minZ);
			ticketNbt.setDouble("maxX", ticket.area.maxX);
			ticketNbt.setDouble("maxY", ticket.area.maxY);
			ticketNbt.setDouble("maxZ", ticket.area.maxZ);

			ticketsNbt.appendTag(ticketNbt);
		}
		nbt.setTag("tickets", ticketsNbt);

		return nbt;
	}

	@Override
	public void update() {
		World world = this.getWorldStorage().getWorld();

		if(world.isRemote) {
			return;
		}

		PooledMutableBlockPos checkPos1 = PooledMutableBlockPos.retain();
		PooledMutableBlockPos checkPos2 = PooledMutableBlockPos.retain();

		try {
			Iterator<Ticket> it = this.tickets.iterator();
			while(it.hasNext()) {
				Ticket ticket = it.next();

				checkPos1.setPos(ticket.area.minX, ticket.area.minY, ticket.area.minZ);
				checkPos2.setPos(ticket.area.maxX, ticket.area.maxY, ticket.area.maxZ);

				ticket.loaded = world.isAreaLoaded(checkPos1, checkPos2);

				if(ticket.loaded) {
					ticket.counter++;

					if(ticket.counter >= this.expirationTime) {
						it.remove();
						this.key2tickets.remove(ticket.key);
					}
				}
			}
		} finally {
			checkPos1.release();
			checkPos2.release();
		}

		if(this.tickets.isEmpty()) {
			this.getWorldStorage().getLocalStorageHandler().removeLocalStorage(this);
			return;
		}

		long worldTime = world.getTotalWorldTime();
		long ticks = this.useWorldtime ? Math.max(worldTime - this.lastCheckedTime, 0) : 1;
		this.lastCheckedTime = worldTime;

		long decay = Math.max(this.sharedTokens - (long)Math.floor(this.sharedTokens * this.limitMultiplier) - 1, 0);

		long newTokens = Math.max(this.generateTokens(ticks) - decay, 0);

		int n = this.tickets.size();

		if(newTokens < n) {
			for(int i = 0; i < newTokens; i++) {
				Ticket ticket = this.tickets.get(world.rand.nextInt(n));

				if(ticket.loaded) {
					this.sharedTokens++;
				} else {
					ticket.reservedTokens++;
				}
			}
		} else {
			long f = newTokens / n;
			long r = newTokens % n;

			int i = 0;
			for(Ticket ticket : this.tickets) {
				long ticketFraction;
				if(++i <= r) {
					ticketFraction = f + 1;
				} else {
					ticketFraction = f;
				}

				if(ticket.loaded) {
					this.sharedTokens += ticketFraction;
				} else {
					ticket.reservedTokens += ticketFraction;
				}
			}
		}

		if(BetweenlandsConfig.DEBUG.debug && worldTime % 20 == 0) {
			int reservedTokens = 0;
			for(Ticket ticket : this.tickets) {
				reservedTokens += ticket.reservedTokens;
			}
			this.setName("token_bucket_" + this.bucketId + "_" + this.sharedTokens + "_" + reservedTokens);
		}

		this.markDirty();
	}

	protected long generateTokens(long ticks) {
		if(ticks == 1) {
			return this.getWorldStorage().getWorld().rand.nextInt(Math.max(this.maxTokensPerTick - this.minTokensPerTick, 0) + 1) + this.minTokensPerTick;
		} else {
			float tokens = ticks * (this.maxTokensPerTick + this.minTokensPerTick) / 2.0f;
			return this.getWorldStorage().getWorld().rand.nextBoolean() ? MathHelper.floor(tokens) : MathHelper.ceil(tokens);
		}
	}

}

package thebetweenlands.common.world.storage.location;

import java.util.List;
import java.util.UUID;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import thebetweenlands.api.storage.ILocalStorageHandler;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageUUID;
import thebetweenlands.common.world.storage.BetweenlandsWorldStorage;

public class TokenBucket {
	private World world;
	private BlockPos pos;

	private ResourceLocation bucketId;
	private float sizeX, sizeY, sizeZ;
	private int minTokensPerTick = 1;
	private int maxTokensPerTick = 1;
	private double limitMultiplier = 0.99D;
	private double tokensConsumedPerTick = 1;

	private long lastCheckedTime = Long.MIN_VALUE;
	private double consumedTokenFraction;

	public TokenBucket() { }

	public TokenBucket(NBTTagCompound nbt) {
		this.readFromNBT(nbt);
	}

	public TokenBucket(ResourceLocation bucketId, float sizeX, float sizeY, float sizeZ, int minTokensPerTick, int maxTokensPerTick, double limitMultiplier, double tokensConsumedPerTick) {
		this.bucketId = bucketId;
		this.sizeX = sizeX;
		this.sizeY = sizeY;
		this.sizeZ = sizeZ;
		this.minTokensPerTick = minTokensPerTick;
		this.maxTokensPerTick = maxTokensPerTick;
		this.limitMultiplier = limitMultiplier;
		this.tokensConsumedPerTick = tokensConsumedPerTick;
	}

	public TokenBucket setWorld(World world) {
		this.world = world;
		if(this.lastCheckedTime == Long.MIN_VALUE) {
			this.lastCheckedTime = world.getTotalWorldTime();
		}
		return this;
	}

	public TokenBucket setPos(BlockPos pos) {
		this.pos = pos;
		return this;
	}

	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt.setString("bucketId", this.bucketId.toString());
		nbt.setFloat("sizeX", this.sizeX);
		nbt.setFloat("sizeY", this.sizeY);
		nbt.setFloat("sizeZ", this.sizeZ);
		nbt.setInteger("minTokensPerTick", this.minTokensPerTick);
		nbt.setInteger("maxTokensPerTick", this.maxTokensPerTick);
		nbt.setDouble("limitMultiplier", this.limitMultiplier);
		nbt.setDouble("tokensConsumedPerTick", this.tokensConsumedPerTick);

		nbt.setLong("lastCheckedTime", this.lastCheckedTime);
		nbt.setDouble("consumedTokenFraction", this.consumedTokenFraction);

		return nbt;
	}

	public void readFromNBT(NBTTagCompound nbt) {
		this.bucketId = new ResourceLocation(nbt.getString("bucketId"));
		this.sizeX = nbt.getFloat("sizeX");
		this.sizeY = nbt.getFloat("sizeY");
		this.sizeZ = nbt.getFloat("sizeZ");
		this.minTokensPerTick = nbt.getInteger("minTokensPerTick");
		this.maxTokensPerTick = nbt.getInteger("maxTokensPerTick");
		this.limitMultiplier = nbt.getDouble("limitMultiplier");
		this.tokensConsumedPerTick = nbt.getDouble("tokensConsumedPerTick");

		this.lastCheckedTime = nbt.getLong("lastCheckedTime");
		this.consumedTokenFraction = nbt.getDouble("consumedTokenFraction");
	}

	public long consume() {
		if(this.world == null || this.pos == null || this.bucketId == null) {
			return 0;
		}

		IWorldStorage storage = BetweenlandsWorldStorage.forWorld(this.world);
		ILocalStorageHandler handler = storage.getLocalStorageHandler();

		LocationTokenBucket tokenBucket = null;

		AxisAlignedBB posAabb = new AxisAlignedBB(this.pos);

		List<LocationTokenBucket> locations = handler.getLocalStorages(LocationTokenBucket.class, posAabb, location -> this.bucketId.equals(location.getBucketId()));
		if(!locations.isEmpty()) {
			tokenBucket = locations.get(0);
		}

		if(tokenBucket == null && !this.world.isRemote) {
			tokenBucket = new LocationTokenBucket(storage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(this.pos), posAabb.grow(this.sizeX * 0.5f - 0.49f, this.sizeY * 0.5f - 0.49f, this.sizeZ * 0.5f - 0.49f), this.bucketId);
			tokenBucket.setTokensPerTick(this.minTokensPerTick, this.maxTokensPerTick);
			tokenBucket.setLimitMultiplier(this.limitMultiplier);
			handler.addLocalStorage(tokenBucket);
		}

		if(tokenBucket != null) {
			long worldTime = this.world.getTotalWorldTime();
			long ticks = Math.max(worldTime - this.lastCheckedTime, 0);

			double consumedTokens = ticks * this.tokensConsumedPerTick + this.consumedTokenFraction;
			long wholeConsumedTokens = MathHelper.floor(consumedTokens);

			if(wholeConsumedTokens > 0) {
				this.lastCheckedTime = worldTime;
				this.consumedTokenFraction = consumedTokens - wholeConsumedTokens;

				tokenBucket.refreshTicket(new ResourceLocation(this.bucketId.getNamespace(), String.format("%d_%d_%d", this.pos.getX(), this.pos.getY(), this.pos.getZ())), posAabb);

				return tokenBucket.consumeTokens(wholeConsumedTokens);
			}
		}

		return 0;
	}
}
